//! Working an area with a real (simulated) brush.
//!
//! `Handling` describes how a painter works a region: which tool, how long
//! the strokes are and which way they run, how hard they press, how often
//! they go back to the palette and whether they wipe the brush first.
//! `Canvas::work` then drives a `Held` brush over the region stroke by
//! stroke, so all mixing, smearing, dry-brush and ridges come from the
//! bristle simulation, not from blend modes.

use crate::bristle::{Gesture, Held, Orient, Rect, Tool, footprint};
use crate::canvas::Canvas;
use crate::color::{Rgb, from_oklab, to_oklab};
use crate::mask::Mask;
use crate::palette::Palette;
use crate::rng::Rng;
use crate::wet::Paint;
use rayon::prelude::*;

type Field<'a, T> = Box<dyn Fn(f32, f32) -> T + Sync + 'a>;

pub struct Handling<'a> {
    pub tool: Tool,
    /// Stroke length range in units.
    pub length: (f32, f32),
    /// How many layers of strokes cover each point on average.
    pub coverage: f32,
    /// Stroke direction field (radians, 0 = left→right).
    pub angle: Field<'a, f32>,
    pub angle_jitter: f32,
    /// Color mixed on the palette for a stroke centered at a point.
    pub color: Field<'a, Rgb>,
    /// Palette-mixing inconsistency per dip: OKLab L and a/b sd.
    pub jitter: (f32, f32),
    /// Hiding and stiffness of the paint when it isn't mixed from a
    /// palette (see `Paint`).
    pub hiding: f32,
    pub stiff: f32,
    /// Mix each pile from these tube paints, thinned with this fraction of
    /// oil medium (0..1). The color field is then what the painter aims for.
    pub palette: Option<(&'a Palette, f32)>,
    /// How unevenly each pile is mixed: relative sd of the proportions.
    pub mix_jitter: f32,
    /// Where the painter loads the brush more or less (multiplies `load`,
    /// evaluated at each stroke's center): a glaze goes on deeper where the
    /// brush carries more.
    pub load_at: Option<Field<'a, f32>>,
    /// Pressure range (a random value in it per stroke).
    pub pressure: (f32, f32),
    pub orient: Orient,
    /// Strokes between trips to the palette.
    pub dip_every: usize,
    /// How much of a full load a dip takes.
    pub load: f32,
    /// Fraction of old paint wiped off before each dip (1 = clean, 0 = dirty).
    pub wipe: f32,
    /// Clean blender: never loads paint, wiped every `dip_every` strokes.
    pub blender: bool,
    /// Scumble: short back-and-forth strokes instead of single pulls.
    pub scrub: usize,
    /// Clip bristle contact to the mask (crisp, cut-in edges).
    pub clip: bool,
    /// Minimum mask value for a stroke center.
    pub threshold: f32,
    /// Press-down and lift-off fractions of each stroke.
    pub ramps: (f32, f32),
    /// Hand unsteadiness (1 = normal).
    pub shake: f32,
}

impl<'a> Handling<'a> {
    pub fn new(tool: Tool) -> Self {
        Handling {
            tool,
            length: (30.0, 90.0),
            coverage: 2.0,
            angle: Box::new(|_, _| 0.0),
            angle_jitter: 0.08,
            color: Box::new(|_, _| [0.5; 3]),
            jitter: (0.02, 0.006),
            hiding: 0.85,
            stiff: 0.8,
            pressure: (0.6, 0.9),
            orient: Orient::Across,
            dip_every: 1,
            load: 0.8 * 0.8,
            wipe: 0.6,
            blender: false,
            scrub: 0,
            clip: false,
            threshold: 0.3,
            ramps: (0.08, 0.15),
            shake: 1.0,
            palette: None,
            mix_jitter: 0.08,
            load_at: None,
        }
    }
    pub fn length(mut self, a: f32, b: f32) -> Self {
        self.length = (a, b);
        self
    }
    pub fn coverage(mut self, c: f32) -> Self {
        self.coverage = c;
        self
    }
    pub fn angle(mut self, f: impl Fn(f32, f32) -> f32 + Sync + 'a) -> Self {
        self.angle = Box::new(f);
        self
    }
    pub fn angle_jitter(mut self, a: f32) -> Self {
        self.angle_jitter = a;
        self
    }
    pub fn color(mut self, f: impl Fn(f32, f32) -> Rgb + Sync + 'a) -> Self {
        self.color = Box::new(f);
        self
    }
    pub fn jitter(mut self, l: f32, hue: f32) -> Self {
        self.jitter = (l, hue);
        self
    }
    /// A fixed paint (no palette mixing).
    pub fn paint(mut self, hiding: f32, stiff: f32) -> Self {
        self.hiding = hiding;
        self.stiff = stiff;
        self.palette = None;
        self
    }
    /// Mix every pile from `palette`'s tubes, thinned with `medium` (0..1).
    pub fn mixed(mut self, palette: &'a Palette, medium: f32) -> Self {
        self.palette = Some((palette, medium));
        self
    }
    /// Change how much medium goes into the palette mixtures.
    pub fn medium(mut self, medium: f32) -> Self {
        let (p, _) = self.palette.expect("medium() needs a palette: use mixed()");
        self.palette = Some((p, medium));
        self
    }
    /// Vary the load across the canvas (see `load_at`).
    pub fn load_at(mut self, f: impl Fn(f32, f32) -> f32 + Sync + 'a) -> Self {
        self.load_at = Some(Box::new(f));
        self
    }
    pub fn mix_jitter(mut self, sd: f32) -> Self {
        self.mix_jitter = sd;
        self
    }
    /// How much paint each trip to the palette puts on the brush (0..1 of full).
    pub fn load(mut self, amount: f32) -> Self {
        self.load = amount;
        self
    }
    pub fn pressure(mut self, a: f32, b: f32) -> Self {
        self.pressure = (a, b);
        self
    }
    pub fn orient(mut self, o: Orient) -> Self {
        self.orient = o;
        self
    }
    pub fn dips(mut self, every: usize, load: f32, wipe: f32) -> Self {
        self.dip_every = every.max(1);
        self.load = load;
        self.wipe = wipe;
        self
    }
    pub fn blender(mut self) -> Self {
        self.blender = true;
        self
    }
    pub fn scrub(mut self, n: usize) -> Self {
        self.scrub = n;
        self
    }
    pub fn clip(mut self, on: bool) -> Self {
        self.clip = on;
        self
    }
    pub fn threshold(mut self, t: f32) -> Self {
        self.threshold = t;
        self
    }
    pub fn ramps(mut self, attack: f32, release: f32) -> Self {
        self.ramps = (attack, release);
        self
    }
    pub fn shake(mut self, k: f32) -> Self {
        self.shake = k;
        self
    }
}

/// One planned stroke.
struct Plan {
    pts: Vec<(f32, f32)>,
    pressure: f32,
    fade: f32,
    /// Paint to dip into before this stroke (None = no trip to the palette).
    dip: Option<Paint>,
    /// How much of a full load that dip takes.
    load: f32,
}

impl Canvas {
    /// Work the region `mask` with a simulated brush, stroke by stroke.
    ///
    /// Strokes are planned up front, then grouped into square passages
    /// (tiles) larger than twice any stroke's reach. Passages in a 2×2
    /// checkerboard phase can't share a pixel, so each gets its own brush and
    /// they are painted in parallel; phases run one after another.
    pub fn work(&mut self, mask: &Mask, hd: &Handling, seed: u64) {
        self.check_mask(mask);
        let mut rng = Rng::new(seed);
        let f = self.f;
        let mean_len = 0.5 * (hd.length.0 + hd.length.1);
        // one stroke per gap² of area gives coverage = width · length / gap²
        let gap = (hd.tool.width * mean_len.max(hd.tool.width) / hd.coverage.max(0.05)).sqrt().max(0.5);
        let (cols, rows) = ((f.width() / gap).ceil() as usize + 1, (f.height() / gap).ceil() as usize + 1);
        let mut centers = Vec::new();
        for j in 0..rows {
            for i in 0..cols {
                let x = (i as f32 + rng.f()) * gap;
                let y = (j as f32 + rng.f()) * gap;
                if x > f.width() || y > f.height() {
                    continue;
                }
                if mask.data[f.index(x, y)] >= hd.threshold {
                    centers.push((x, y));
                }
            }
        }
        for i in (1..centers.len()).rev() {
            let j = (rng.next_u64() % (i as u64 + 1)) as usize;
            centers.swap(i, j);
        }
        if centers.is_empty() {
            return;
        }

        // plan every stroke deterministically
        let mut plans = Vec::with_capacity(centers.len());
        // how far (units) any stroke's pixel footprint reaches from its center
        let (mut ex, mut ey) = (0.0f32, 0.0f32);
        for &(cx, cy) in &centers {
            let len = rng.range(hd.length.0, hd.length.1);
            let bend = rng.normal() * hd.angle_jitter;
            let pts: Vec<(f32, f32)> = if hd.scrub > 0 {
                let a = (hd.angle)(cx, cy) + bend;
                let (ca, sa) = (a.cos(), a.sin());
                let (nx, ny) = (-sa, ca);
                let amp = len * 0.5;
                let adv = hd.tool.width * 0.35;
                (0..=hd.scrub * 2)
                    .map(|k| {
                        let s = if k % 2 == 0 { -amp } else { amp };
                        let t = (k as f32 - hd.scrub as f32) * adv * 0.5;
                        (cx + ca * s + nx * t + rng.normal() * 1.5, cy + sa * s + ny * t + rng.normal() * 1.5)
                    })
                    .collect()
            } else {
                trace(&*hd.angle, cx, cy, len, bend, &mut rng)
            };
            let rect = footprint(&hd.tool, &pts, hd.shake, f.scale, f.w, f.h);
            if let Some(r) = rect {
                let (px, py) = (cx * f.scale, cy * f.scale);
                ex = ex.max((px - r.0 as f32).max(r.2 as f32 - px) / f.scale);
                ey = ey.max((py - r.1 as f32).max(r.3 as f32 - py) / f.scale);
            }
            let pressure = rng.range(hd.pressure.0, hd.pressure.1);
            let fade = rng.range(0.75, 1.05);
            let target = (hd.color)(cx, cy);
            let paint = match hd.palette {
                // on the palette: mix the pile from tubes, never twice alike
                Some((pal, medium)) => pal.remix(&pal.mix(target), hd.mix_jitter, &mut rng).paint(medium),
                None => {
                    let lab = to_oklab(target);
                    let col = from_oklab([
                        lab[0] + rng.normal() * hd.jitter.0,
                        lab[1] + rng.normal() * hd.jitter.1,
                        lab[2] + rng.normal() * hd.jitter.1,
                    ]);
                    Paint { color: col, hiding: hd.hiding, stiff: hd.stiff }
                }
            };
            let load = hd.load * hd.load_at.as_ref().map_or(1.0, |f| f(cx, cy).max(0.0));
            plans.push((cx, cy, rect, Plan { pts, pressure, fade, dip: Some(paint), load }));
        }
        // tiles are sized per axis from the footprints: tiles painted at the
        // same time are one tile apart, so a tile at least twice the largest
        // reach keeps their pixels disjoint (long horizontal strokes get wide,
        // short tiles)
        let margin = 2.0 / f.scale;
        let (tile_x, tile_y) = ((2.0 * ex + margin).max(gap * 2.0), (2.0 * ey + margin).max(gap * 2.0));
        let (tw, th) = ((f.width() / tile_x).ceil().max(1.0) as usize, (f.height() / tile_y).ceil().max(1.0) as usize);
        if std::env::var_os("PAINT_DEBUG").is_some() {
            eprintln!("work: {} strokes, reach {ex:.0}x{ey:.0}, tiles {tw}x{th}", centers.len());
        }
        let mut tiles: Vec<Vec<Plan>> = (0..tw * th).map(|_| Vec::new()).collect();
        // pixel footprint of each tile: the union of its strokes'
        let mut tile_rect: Vec<Option<Rect>> = vec![None; tw * th];
        for (cx, cy, rect, p) in plans {
            let tx = ((cx / tile_x) as usize).min(tw - 1);
            let ty = ((cy / tile_y) as usize).min(th - 1);
            let t = ty * tw + tx;
            if let Some(r) = rect {
                tile_rect[t] = Some(match tile_rect[t] {
                    None => r,
                    Some(a) => (a.0.min(r.0), a.1.min(r.1), a.2.max(r.2), a.3.max(r.3)),
                });
                tiles[t].push(p);
            }
        }
        // trips to the palette: every `dip_every` strokes within a passage
        for t in tiles.iter_mut() {
            for (k, p) in t.iter_mut().enumerate() {
                if k % hd.dip_every != 0 {
                    p.dip = None;
                }
            }
        }
        let n_strokes: usize = tiles.iter().map(|t| t.len()).sum();
        let first_id = self.next_stroke_ids(n_strokes as u32);
        let mut offsets = Vec::with_capacity(tiles.len());
        let mut acc = 0u32;
        for t in &tiles {
            offsets.push(acc);
            acc += t.len() as u32;
        }

        let surf = self.surf();
        let clip = if hd.clip { Some(mask) } else { None };
        let mut phases = [(0usize, 0usize), (1, 0), (0, 1), (1, 1)];
        for i in (1..4).rev() {
            let j = (rng.next_u64() % (i as u64 + 1)) as usize;
            phases.swap(i, j);
        }
        let mut dirty: crate::bristle::Bounds = None;
        for (px, py) in phases {
            let idx: Vec<usize> = (0..tiles.len()).filter(|&i| (i % tw) % 2 == px && (i / tw) % 2 == py && tile_rect[i].is_some()).collect();
            let batches = disjoint_batches(&idx, &tile_rect);
            if std::env::var_os("PAINT_DEBUG").is_some() {
                eprintln!("  phase: {} tiles in {} batches", idx.len(), batches.len());
            }
            for batch in batches {
                let results: Vec<crate::bristle::Bounds> = batch
                    .par_iter()
                    .map(|&ti| {
                        let mut held = Held::new(hd.tool.clone(), seed ^ 0x5EED ^ (ti as u64).wrapping_mul(0x9E37_79B9));
                        let mut scratch = Vec::new();
                        let mut b: crate::bristle::Bounds = None;
                        for (k, p) in tiles[ti].iter().enumerate() {
                            if let Some(paint) = p.dip {
                                if hd.blender {
                                    held.wipe(0.9);
                                } else {
                                    held.wipe(hd.wipe);
                                    held.load(paint, p.load);
                                }
                            }
                            let g = Gesture::new(p.pts.clone())
                                .pressure(p.pressure, p.pressure * p.fade)
                                .orient(hd.orient)
                                .ramps(hd.ramps.0, hd.ramps.1)
                                .shake(hd.shake);
                            let id = first_id.wrapping_add(offsets[ti] + k as u32);
                            // SAFETY: every pixel this drag touches lies in its
                            // stroke footprint, inside this tile's rect; tiles in
                            // one batch have disjoint rects; `surf()` checked the
                            // buffers match the frame.
                            let r = unsafe { crate::bristle::drag_on(surf, &mut held, &g, clip, id, &mut scratch) };
                            if let Some((a, c, d, e)) = r {
                                b = Some(match b {
                                    None => (a, c, d, e),
                                    Some((a0, c0, d0, e0)) => (a0.min(a), c0.min(c), d0.max(d), e0.max(e)),
                                });
                            }
                        }
                        b
                    })
                    .collect();
                for r in results.into_iter().flatten() {
                    dirty = Some(match dirty {
                        None => r,
                        Some((a0, c0, d0, e0)) => (a0.min(r.0), c0.min(r.1), d0.max(r.2), e0.max(r.3)),
                    });
                }
            }
        }
        if let Some((x0, y0, x1, y1)) = dirty {
            self.wet.touch(x0, y0, x1, y1);
        }
    }
}

/// Group tiles (in the given, deterministic order) into batches whose
/// footprints are pairwise disjoint; tiles in a batch may run concurrently.
fn disjoint_batches(idx: &[usize], rects: &[Option<Rect>]) -> Vec<Vec<usize>> {
    let overlaps = |a: Rect, b: Rect| a.0 < b.2 && b.0 < a.2 && a.1 < b.3 && b.1 < a.3;
    let mut batches: Vec<(Vec<usize>, Vec<Rect>)> = Vec::new();
    for &ti in idx {
        let r = rects[ti].expect("tile without footprint");
        match batches.iter_mut().find(|(_, rs)| rs.iter().all(|&q| !overlaps(q, r))) {
            Some((ts, rs)) => {
                ts.push(ti);
                rs.push(r);
            }
            None => batches.push((vec![ti], vec![r])),
        }
    }
    batches.into_iter().map(|(ts, _)| ts).collect()
}

/// A streamline through (cx, cy) along the angle field, random direction.
fn trace(angle: &(dyn Fn(f32, f32) -> f32 + Sync), cx: f32, cy: f32, len: f32, bend: f32, rng: &mut Rng) -> Vec<(f32, f32)> {
    let steps = 3;
    let h = len / (2 * steps) as f32;
    let mut fwd = vec![(cx, cy)];
    let mut back = vec![];
    let (mut x, mut y) = (cx, cy);
    for k in 0..steps {
        let a = angle(x, y) + bend * (1.0 + k as f32 * 0.3);
        x += a.cos() * h;
        y += a.sin() * h;
        fwd.push((x, y));
    }
    let (mut x, mut y) = (cx, cy);
    for k in 0..steps {
        let a = angle(x, y) + bend * (1.0 + k as f32 * 0.3);
        x -= a.cos() * h;
        y -= a.sin() * h;
        back.push((x, y));
    }
    back.reverse();
    back.extend(fwd);
    if rng.chance(0.5) {
        back.reverse();
    }
    back
}
//! A painter's hand working at one spot: a local frame (origin, scale, and
//! "up") so a small motif can be written as a list of brush gestures in its
//! own coordinates. It knows nothing about what is painted; figures and other
//! motifs are written stroke by stroke in the paintings themselves.

use crate::bristle::{Gesture, Held, Orient, Tool};
use crate::canvas::Canvas;
use crate::mask::Mask;
use crate::rng::Rng;
use crate::wet::Paint;

pub struct Hand {
    /// Origin in canvas units (e.g. between a figure's feet).
    pub at: (f32, f32),
    /// Canvas units per local unit (e.g. a figure's height).
    pub size: f32,
    /// Tremor: random offset of each control point, in local units.
    pub tremor: f32,
    pub rng: Rng,
}

/// One gesture in local coordinates: `u` across (+ right), `v` up.
pub struct Mark<'a> {
    pub pts: &'a [(f32, f32)],
    /// Pressure at start and end.
    pub pressure: (f32, f32),
    /// Attack and release fractions.
    pub ramps: (f32, f32),
}

impl Hand {
    pub fn new(at: (f32, f32), size: f32, seed: u64) -> Self {
        Hand { at, size, tremor: 0.004, rng: Rng::new(seed) }
    }

    /// Local (u, v) to canvas units.
    pub fn p(&self, u: f32, v: f32) -> (f32, f32) {
        (self.at.0 + u * self.size, self.at.1 - v * self.size)
    }

    /// Pick up a brush of `width` local units, loaded with `paint`.
    pub fn take(&mut self, tool: fn(f32) -> Tool, width: f32, paint: Paint, load: f32) -> Held {
        let mut h = Held::new(tool(width * self.size), self.rng.next_u64());
        h.load(paint, load);
        h
    }

    /// Drag the held brush through local points.
    pub fn mark(&mut self, c: &mut Canvas, held: &mut Held, m: Mark, clip: Option<&Mask>) {
        let t = self.tremor;
        let pts: Vec<(f32, f32)> = m
            .pts
            .iter()
            .map(|&(u, v)| {
                let (du, dv) = (self.rng.normal() * t, self.rng.normal() * t);
                self.p(u + du, v + dv)
            })
            .collect();
        let g = Gesture::new(pts).pressure(m.pressure.0, m.pressure.1).ramps(m.ramps.0, m.ramps.1).orient(Orient::Across);
        c.drag(held, &g, clip);
    }

    /// Shorthand: a stroke with given pressures and default ramps.
    pub fn line(&mut self, c: &mut Canvas, held: &mut Held, pts: &[(f32, f32)], p0: f32, p1: f32) {
        self.mark(c, held, Mark { pts, pressure: (p0, p1), ramps: (0.1, 0.25) }, None);
    }

    /// A dab: a very short press at (u, v) in direction `dir` (radians, 0 = right, up positive).
    pub fn dab(&mut self, c: &mut Canvas, held: &mut Held, u: f32, v: f32, len: f32, dir: f32, p: f32) {
        let (du, dv) = (dir.cos() * len * 0.5, dir.sin() * len * 0.5);
        self.mark(c, held, Mark { pts: &[(u - du, v - dv), (u + du, v + dv)], pressure: (p, p), ramps: (0.0, 0.3) }, None);
    }
}
//! Running a painting from the command line: options, stage timing, stopping
//! early to look at a stage, and the finishing recipe (varnish, cracks,
//! raking light) paintings share.
//!
//!   cargo paint <name>                       1000px preview → out/<name>.png
//!   cargo paint <name> -- --full             3200px         → out/<name>_full.png
//!   cargo paint <name> -- --width 1600 --seed 7 --out path.png
//!   cargo paint <name> -- --stop sky         save right after the "sky" stage
//!   cargo paint <name> -- --no-cracks        skip craquelure in the finish

use paint::{Canvas, Fbm, Pigment, Rgb, hex};
use std::path::PathBuf;
use std::time::Instant;

pub struct Run {
    pub width: usize,
    pub seed: u64,
    pub out: PathBuf,
    stop: Option<String>,
    no_cracks: bool,
    t0: Instant,
}

impl Run {
    pub fn new(name: &str) -> Self {
        let args: Vec<String> = std::env::args().collect();
        let get = |flag: &str| args.iter().position(|a| a == flag).and_then(|i| args.get(i + 1));
        let has = |flag: &str| args.iter().any(|a| a == flag);
        let full = has("--full");
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../out");
        let out = match get("--out") {
            Some(p) => p.into(),
            None if full => root.join(format!("{name}_full.png")),
            None => root.join(format!("{name}.png")),
        };
        Run {
            width: get("--width").and_then(|s| s.parse().ok()).unwrap_or(if full { 3200 } else { 1000 }),
            seed: get("--seed").and_then(|s| s.parse().ok()).unwrap_or(1),
            out,
            stop: get("--stop").cloned(),
            no_cracks: has("--no-cracks"),
            t0: Instant::now(),
        }
    }

    /// A stage of the painting is done: report the time, and if the run was
    /// asked to stop here, save the canvas and return true (the caller then
    /// returns). Saving dries the wet paint, so a run only saves at its end.
    #[must_use]
    pub fn stage(&self, c: &mut Canvas, name: &str) -> bool {
        eprintln!("  {name:<10} {:>6.2}s", self.t0.elapsed().as_secs_f32());
        if self.stop.as_deref() == Some(name) {
            self.save(c);
            return true;
        }
        false
    }

    /// Finish the painting (see `Finish`) and save it.
    pub fn finish(&self, c: &mut Canvas, f: &Finish) {
        c.dry();
        let var = Fbm::new(self.seed as u32 + 98, 3, 400.0);
        let (base, vary) = (f.varnish_coats, f.varnish_vary);
        c.glaze(&Pigment::varnish(f.varnish), None, |x, y| base + vary * var.get(x, y));
        if let (Some((cell, strength)), false) = (f.cracks, self.no_cracks) {
            c.craquelure(cell, strength, self.seed);
        }
        c.relief(f.relief.0, f.relief.1);
        if !self.stage(c, "finish") {
            self.save(c);
        }
    }

    pub fn save(&self, c: &mut Canvas) {
        c.save(&self.out).unwrap();
        let p = self.out.canonicalize().unwrap_or(self.out.clone());
        eprintln!("wrote {} ({}px) in {:.1}s", p.display(), self.width, self.t0.elapsed().as_secs_f32());
    }
}

/// How a painting is finished: aged varnish (a clear, yellowing film,
/// uneven), craquelure, then the surface lit by raking light.
pub struct Finish {
    pub varnish: Rgb,
    /// Varnish thickness in coats, and how much it varies across the canvas.
    pub varnish_coats: f32,
    pub varnish_vary: f32,
    /// Crack cell size (units) and darkening, if the surface has cracked.
    pub cracks: Option<(f32, f32)>,
    /// Relief lighting strength and gloss.
    pub relief: (f32, f32),
}

impl Finish {
    /// An old varnished painting.
    pub fn aged(relief: (f32, f32)) -> Self {
        Finish { varnish: hex("#e6d3a4"), varnish_coats: 0.4, varnish_vary: 0.12, cracks: Some((12.0, 0.12)), relief }
    }
}
//! Motifs shared by several paintings. Nothing here builds shapes: each motif
//! is a fixed sequence of brush gestures, the way a painter who has painted a
//! figure many times puts it down: which brush, which stroke, in what order.

pub mod figures;
pub mod trees;
pub mod run;

//! Simulated bristle brushes working in wet paint.
//!
//! A `Tool` is a physical brush (round sable, hog flat, filbert, fan, rigger,
//! badger blender). `Held` is that brush in the hand: every bristle has its
//! own little reservoir of paint (volume + Mixbox pigment mix + hiding).
//!
//! As the handle moves along a `Gesture`:
//! - bristles splay with pressure and their tips trail behind the motion,
//!   lagging on turns (a first-order bend model, after the verlet bristles in
//!   dli/paint: https://github.com/dli/paint);
//! - a bristle touches the canvas only where its reach clears the canvas tooth
//!   and the paint relief, so light pressure catches only the weave's peaks
//!   (dry-brush);
//! - each bristle swept capsule exchanges paint with the wet layer: it
//!   deposits a share of its load and picks up wet paint, so brushes get dirty,
//!   colors smear and mix on the canvas, and a clean brush blends;
//! - moving bristles plough wet paint aside and ahead, so ridges and ends of
//!   strokes build up by themselves.

use crate::path::densify;
use crate::canvas::Canvas;
use crate::mask::Mask;
use crate::rng::Rng;
use crate::smoothstep;
use crate::wet::{LAT, Latent, Paint, Prop, mix_into};

/// Relief (µm) that spans a bristle's contact range: a bristle pressed
/// lightly touches only peaks this much above their surroundings.
const TOOTH_UM: f32 = 60.0;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Kind {
    Round,
    Flat,
    Filbert,
    Fan,
    Rigger,
    Blender,
}

#[derive(Clone, Debug)]
pub struct Tool {
    pub kind: Kind,
    /// Footprint width at full pressure (units).
    pub width: f32,
    pub bristles: usize,
    /// How far tips trail behind the contact at full pressure (units).
    pub length: f32,
    /// 0 = soft hair (sable, badger) .. 1 = stiff hog bristle.
    pub stiffness: f32,
    /// Bristle thickness multiplier (overlap between bristles).
    pub hair: f32,
    /// Stroke length (units) over which a load runs down (e-folding).
    pub run: f32,
    /// Paint thickness laid at the start of a fully loaded stroke.
    pub lay: f32,
    /// Fraction of wet paint a bristle takes up per pass.
    pub pickup: f32,
    /// Fraction of wet paint a moving bristle ploughs aside per pass.
    pub push: f32,
    /// Footprint growth under pressure.
    pub splay: f32,
    /// Unevenness of bristle lengths (ragged edges, broken marks).
    pub ragged: f32,
}

impl Tool {
    fn base(kind: Kind, width: f32) -> Self {
        Tool {
            kind,
            width,
            bristles: 80,
            length: width * 0.7,
            stiffness: 0.4,
            hair: 1.3,
            run: 40.0 + 6.0 * width,
            lay: 1.0,
            pickup: 0.12,
            push: 0.1,
            splay: 0.3,
            ragged: 0.25,
        }
    }

    /// Soft pointed round: smooth, precise, little ploughing. Friedrich's detail brush.
    pub fn round_sable(width: f32) -> Self {
        Tool { stiffness: 0.2, pickup: 0.1, push: 0.05, splay: 0.45, ragged: 0.15, ..Self::base(Kind::Round, width) }
    }

    /// Stiff hog-bristle flat: square marks, strong ridges, broken edges.
    pub fn hog_flat(width: f32) -> Self {
        Tool {
            bristles: 140,
            length: width * 0.5,
            stiffness: 0.85,
            hair: 1.1,
            run: 25.0 + 4.0 * width,
            lay: 1.4,
            pickup: 0.2,
            push: 0.3,
            splay: 0.12,
            ragged: 0.45,
            ..Self::base(Kind::Flat, width)
        }
    }

    /// Filbert: oval hog/synthetic, soft-ended marks, good for blending forms.
    pub fn filbert(width: f32) -> Self {
        Tool { bristles: 120, stiffness: 0.6, lay: 1.2, pickup: 0.18, push: 0.18, ragged: 0.3, ..Self::base(Kind::Filbert, width) }
    }

    /// Fan: sparse spread bristles, for foliage, grasses and feathering.
    pub fn fan(width: f32) -> Self {
        Tool { bristles: 36, hair: 0.6, stiffness: 0.5, lay: 0.7, pickup: 0.1, push: 0.08, splay: 0.2, ragged: 0.5, ..Self::base(Kind::Fan, width) }
    }

    /// Rigger / liner: a few very long soft hairs. Twigs, rigging, fine lines.
    pub fn rigger(width: f32) -> Self {
        Tool {
            bristles: 14,
            length: width * 5.0,
            stiffness: 0.08,
            hair: 1.4,
            run: 250.0,
            lay: 1.0,
            pickup: 0.04,
            push: 0.02,
            splay: 0.6,
            ragged: 0.1,
            ..Self::base(Kind::Rigger, width)
        }
    }

    /// Badger blender: big, soft, used clean to fuse wet paint.
    pub fn badger(width: f32) -> Self {
        Tool {
            bristles: 160,
            length: width * 0.6,
            stiffness: 0.15,
            lay: 0.0,
            run: 30.0,
            pickup: 0.3,
            push: 0.04,
            splay: 0.5,
            ragged: 0.2,
            ..Self::base(Kind::Blender, width)
        }
    }

    /// Bristle radius in units.
    pub(crate) fn hair_radius(&self) -> f32 {
        let across = match self.kind {
            Kind::Flat => 0.36,
            Kind::Filbert => 0.6,
            Kind::Fan => 0.12,
            _ => 1.0,
        };
        // area the bristles share, divided among them
        let area = self.width * 0.5 * self.width * 0.5 * across * std::f32::consts::PI;
        (area / (self.bristles as f32 * std::f32::consts::PI)).sqrt() * self.hair
    }
}

#[derive(Clone, Debug)]
pub(crate) struct Bristle {
    /// Root offset in the brush frame (x along the wide axis), roughly −1..1.
    rx: f32,
    ry: f32,
    len: f32,
    /// Pressure needed before this bristle touches.
    thresh: f32,
    bend: (f32, f32),
    seed: u64,
    prev: [Option<(f32, f32)>; 2],
    pub(crate) vol: f32,
    lat: Latent,
    hide: Prop,
}

/// A brush in the hand, with paint in its bristles.
pub struct Held {
    pub tool: Tool,
    pub(crate) bristles: Vec<Bristle>,
}

impl Held {
    pub fn new(tool: Tool, seed: u64) -> Self {
        let mut rng = Rng::new(seed);
        let n = tool.bristles.max(1);
        let golden = std::f32::consts::PI * (3.0 - 5f32.sqrt());
        let bristles = (0..n)
            .map(|i| {
                let t = (i as f32 + 0.5) / n as f32;
                let (rx, ry) = match tool.kind {
                    Kind::Round | Kind::Rigger | Kind::Blender => {
                        let r = t.sqrt();
                        let a = i as f32 * golden;
                        (r * a.cos(), r * a.sin())
                    }
                    Kind::Filbert => {
                        let r = t.sqrt();
                        let a = i as f32 * golden;
                        (r * a.cos(), r * a.sin() * 0.3)
                    }
                    Kind::Flat => (rng.range(-1.0, 1.0), rng.range(-0.18, 0.18)),
                    Kind::Fan => {
                        let a = rng.range(-0.95, 0.95);
                        (a.sin(), (a.cos() - 1.0) * 0.35 + rng.range(-0.04, 0.04))
                    }
                };
                // jitter roots a little so bristles don't sit on a perfect lattice
                let (rx, ry) = ((rx + rng.normal() * 0.02).clamp(-ROOT_MAX, ROOT_MAX), (ry + rng.normal() * 0.02).clamp(-ROOT_MAX, ROOT_MAX));
                Bristle {
                    rx,
                    ry,
                    len: (1.0 + rng.normal() * 0.15 * tool.ragged).clamp(0.4, LEN_MAX),
                    // a round brush is shaped to a point: the outer hairs are
                    // shorter and touch only under pressure, so a light touch
                    // or a lift-off gives just the tip
                    thresh: tool.ragged * rng.f().powf(1.5) * 0.55
                        + match tool.kind {
                            Kind::Round | Kind::Rigger => 0.6 * (rx * rx + ry * ry),
                            Kind::Filbert => 0.3 * (rx * rx + ry * ry / 0.09),
                            _ => 0.0,
                        },
                    bend: (0.0, 0.0),
                    seed: i as u64 * 7919 + seed,
                    prev: [None, None],
                    vol: 0.0,
                    lat: [0.0; LAT],
                    hide: [0.5, 0.5],
                }
            })
            .collect();
        Held { tool, bristles }
    }

    /// A full load's volume for one bristle.
    pub(crate) fn full(&self) -> f32 {
        // neighbouring bristles overlap by ~hair², so each lays lay / hair²
        let track = 2.0 * self.tool.hair_radius();
        self.tool.lay.max(0.3) * track * self.tool.run / (self.tool.hair * self.tool.hair)
    }

    /// Dip the brush: mix `amount` (0..1 of a full load) of `paint` into
    /// every bristle's reservoir. Bristles hold a little more or less.
    pub fn load(&mut self, paint: Paint, amount: f32) {
        let lat = paint.latent();
        let full = self.full();
        for (i, b) in self.bristles.iter_mut().enumerate() {
            let k = 0.75 + 0.5 * crate::rng::hash2(i as i64, 17, 3);
            mix_into(&mut b.vol, &mut b.lat, &mut b.hide, amount * full * k, &lat, [paint.hiding, paint.stiff]);
        }
    }

    /// Wipe the brush on a rag: remove `frac` of the paint in it.
    pub fn wipe(&mut self, frac: f32) {
        for b in &mut self.bristles {
            b.vol *= 1.0 - frac.clamp(0.0, 1.0);
        }
    }

    /// Wipe thoroughly and load fresh paint.
    pub fn reload(&mut self, paint: Paint, amount: f32) {
        self.wipe(0.85);
        self.load(paint, amount);
    }

    /// Paint left in the brush, relative to a full load.
    pub fn fullness(&self) -> f32 {
        let f = self.full();
        self.bristles.iter().map(|b| b.vol).sum::<f32>() / (f * self.bristles.len() as f32)
    }
}

/// How the brush's wide axis is held.
#[derive(Clone, Copy, Debug)]
pub enum Orient {
    /// Wide axis across the direction of travel (full-width marks).
    Across,
    /// Wide axis along the travel (thin edge marks).
    Along,
    /// Fixed angle in radians, regardless of travel (e.g. Cézanne hatching).
    Fixed(f32),
}

/// One movement of the hand.
#[derive(Clone, Debug)]
pub struct Gesture {
    pub pts: Vec<(f32, f32)>,
    /// Pressure at the start and end (0..1).
    pub pressure: (f32, f32),
    pub orient: Orient,
    /// Fraction of the stroke spent pressing down / lifting off.
    pub attack: f32,
    pub release: f32,
    /// Hand unsteadiness: 1 = a normal hand, 0 = mechanically exact.
    pub shake: f32,
}

impl Gesture {
    pub fn new(pts: Vec<(f32, f32)>) -> Self {
        Gesture { pts, pressure: (0.8, 0.8), orient: Orient::Across, attack: 0.08, release: 0.15, shake: 1.0 }
    }
    pub fn line(a: (f32, f32), b: (f32, f32)) -> Self {
        Self::new(vec![a, b])
    }
    /// Scale hand unsteadiness (0 = exact, 1 = normal).
    pub fn shake(mut self, k: f32) -> Self {
        self.shake = k;
        self
    }
    pub fn pressure(mut self, a: f32, b: f32) -> Self {
        self.pressure = (a, b);
        self
    }
    pub fn orient(mut self, o: Orient) -> Self {
        self.orient = o;
        self
    }
    pub fn ramps(mut self, attack: f32, release: f32) -> Self {
        self.attack = attack;
        self.release = release;
        self
    }
    fn pressure_at(&self, u: f32) -> f32 {
        let base = self.pressure.0 + (self.pressure.1 - self.pressure.0) * u;
        let a = if self.attack > 0.0 { 0.08 + 0.92 * smoothstep(0.0, self.attack, u) } else { 1.0 };
        let r = if self.release > 0.0 { 0.05 + 0.95 * smoothstep(0.0, self.release, 1.0 - u) } else { 1.0 };
        base * a * r
    }
}

/// Raw view of the wet layer and surface, so brushes working disjoint parts
/// of the canvas can run in parallel (see `Canvas::work`).
#[derive(Clone, Copy)]
pub(crate) struct Surf {
    w: usize,
    h: usize,
    scale: f32,
    vol: *mut f32,
    lat: *mut Latent,
    hide: *mut Prop,
    stroke: *mut u32,
    touched: *mut u32,
    floor: *mut f32,
    base: *const f32,
}
// SAFETY: callers only run brushes concurrently on pixel sets that cannot
// overlap (tiles separated by more than the largest stroke extent).
unsafe impl Send for Surf {}
unsafe impl Sync for Surf {}

/// Dirty pixel bounds collected by a drag.
pub(crate) type Bounds = Option<(usize, usize, usize, usize)>;

fn grow(b: &mut Bounds, x0: usize, y0: usize, x1: usize, y1: usize) {
    *b = Some(match *b {
        None => (x0, y0, x1, y1),
        Some((a, c, d, e)) => (a.min(x0), c.min(y0), d.max(x1), e.max(y1)),
    });
}

impl Surf {
    #[inline]
    unsafe fn add(&self, i: usize, v: f32, lat: &Latent, hide: Prop) {
        unsafe {
            if v <= 0.0 {
                return;
            }
            let vol = &mut *self.vol.add(i);
            let l = &mut *self.lat.add(i);
            let hd = &mut *self.hide.add(i);
            let t = *vol + v;
            let a = v / t;
            for k in 0..LAT {
                l[k] += (lat[k] - l[k]) * a;
            }
            hd[0] += (hide[0] - hd[0]) * a;
            hd[1] += (hide[1] - hd[1]) * a;
            *vol = t;
        }
    }
}

impl Canvas {
    pub(crate) fn surf(&mut self) -> Surf {
        // the raw views below index 0..w*h: every buffer must be that long
        let n = self.f.w * self.f.h;
        let wt = &self.wet;
        assert!(
            [self.height.len(), self.px.len(), self.film.len(), wt.vol.len(), wt.lat.len(), wt.hide.len(), wt.stroke.len(), wt.touched.len(), wt.floor.len()].iter().all(|&l| l == n),
            "canvas buffers out of sync with frame"
        );
        if self.base.as_ref().map(|b| b.0) != Some(self.surf_gen) {
            let mut base = self.base.take().map(|b| b.1).unwrap_or_default();
            base.resize(self.height.len(), 0.0);
            use rayon::prelude::*;
            // a brush rests on local peaks: only relief relative to the
            // surroundings (within ~1.5 mm) matters. ±TOOTH_UM of relief spans
            // the whole contact range.
            let r = ((1.5 / self.px_mm()).round() as usize).max(1);
            let (w, h) = (self.f.w, self.f.h);
            let low = crate::surface::box_blur(&crate::surface::box_blur(&self.height, w, h, r), w, h, r);
            base.par_iter_mut().zip(self.height.par_iter().zip(low.par_iter())).for_each(|(b, (&hgt, &lo))| {
                *b = (0.5 + (hgt - lo) / (2.0 * TOOTH_UM)).clamp(-0.2, 1.3);
            });
            self.base = Some((self.surf_gen, base));
        }
        Surf {
            w: self.f.w,
            h: self.f.h,
            scale: self.f.scale,
            vol: self.wet.vol.as_mut_ptr(),
            lat: self.wet.lat.as_mut_ptr(),
            hide: self.wet.hide.as_mut_ptr(),
            stroke: self.wet.stroke.as_mut_ptr(),
            touched: self.wet.touched.as_mut_ptr(),
            floor: self.wet.floor.as_mut_ptr(),
            base: self.base.as_ref().unwrap().1.as_ptr(),
        }
    }

    pub(crate) fn next_stroke_ids(&mut self, n: u32) -> u32 {
        let first = self.wet.current.wrapping_add(1).max(1);
        self.wet.current = first.wrapping_add(n);
        first
    }

    /// Drag a held brush through a gesture, working the wet paint.
    pub fn drag(&mut self, held: &mut Held, g: &Gesture, clip: Option<&Mask>) {
        if let Some(m) = clip {
            self.check_mask(m);
        }
        let id = self.next_stroke_ids(1);
        let surf = self.surf();
        let mut scratch = Vec::new();
        // SAFETY: exclusive &mut self, single brush.
        let b = unsafe { drag_on(surf, held, g, clip, id, &mut scratch) };
        if let Some((x0, y0, x1, y1)) = b {
            self.wet.touch(x0, y0, x1, y1);
        }
    }
}

/// Bristle roots never sit farther than this (in half-widths) from the axis.
const ROOT_MAX: f32 = 1.2;
/// Longest bristle relative to the tool's length.
const LEN_MAX: f32 = 1.6;

/// A pixel rectangle (x0, y0, x1, y1), end-exclusive.
pub(crate) type Rect = (usize, usize, usize, usize);

/// Every pixel `drag_on` may read or write for a gesture with these points
/// (units), as a conservative end-exclusive rectangle clamped to the canvas.
/// Mirrors the geometry in `drag_on`/`exchange`: the resampled path (a spline
/// can overshoot its control points), hand shake, root offsets with wander
/// and splay, bristle bend (it relaxes from zero toward targets bounded by
/// the trail and spread), the capsule radius, and the plough destination.
pub(crate) fn footprint(tool: &Tool, pts: &[(f32, f32)], shake: f32, scale: f32, w: usize, h: usize) -> Option<Rect> {
    if pts.is_empty() {
        return None;
    }
    let s = scale;
    let px: Vec<(f32, f32)> = pts.iter().map(|&(x, y)| (x * s, y * s)).collect();
    let path = if px.len() >= 2 { densify(&px) } else { px };
    let (mut x0, mut y0, mut x1, mut y1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
    for &(x, y) in &path {
        x0 = x0.min(x);
        y0 = y0.min(y);
        x1 = x1.max(x);
        y1 = y1.max(y);
    }
    let shake_px = shake.abs() * (0.05 * tool.width + 0.12) * s * 1.5;
    let half = tool.width * 0.5 * s * (1.0 + tool.splay.abs() * 0.5);
    let root = (ROOT_MAX + 0.12 * tool.ragged.abs()) * std::f32::consts::SQRT_2 * half;
    let bend = tool.length * s * LEN_MAX + root * tool.splay.abs() * 0.3;
    let rb = (tool.hair_radius() * s).max(0.55);
    // exchange rect: capsule ± (rb + 1); plough target ≤ off from a pixel in
    // it, off = rb + 1; bounds padding off + 2; plus rounding
    let pad = shake_px + root + bend * 0.6 + (rb + 1.0) + 2.0 * (rb + 1.0) + 4.0;
    if !pad.is_finite() || !x0.is_finite() || !x1.is_finite() || !y0.is_finite() || !y1.is_finite() {
        panic!("non-finite brush footprint (gesture or tool parameters)");
    }
    let c = |v: f32, n: usize| (v.max(0.0) as usize).min(n);
    let r = (c((x0 - pad).floor(), w), c((y0 - pad).floor(), h), c((x1 + pad).ceil() + 1.0, w), c((y1 + pad).ceil() + 1.0, h));
    if r.2 <= r.0 || r.3 <= r.1 { None } else { Some(r) }
}

/// SAFETY: no other thread may touch pixels in `footprint(..)` of `g`.
pub(crate) unsafe fn drag_on(
    sf: Surf,
    held: &mut Held,
    g: &Gesture,
    clip: Option<&Mask>,
    id: u32,
    scratch: &mut Vec<f32>,
) -> Bounds {
    let mut bounds: Bounds = None;
    if g.pts.is_empty() {
        return bounds;
    }
    let s = sf.scale;
    let pts: Vec<(f32, f32)> = g.pts.iter().map(|&(x, y)| (x * s, y * s)).collect();
    let path = if pts.len() >= 2 { densify(&pts) } else { vec![pts[0], pts[0]] };
    let mut arc = vec![0.0f32; path.len()];
    for i in 1..path.len() {
        let (dx, dy) = (path[i].0 - path[i - 1].0, path[i].1 - path[i - 1].1);
        arc[i] = arc[i - 1] + (dx * dx + dy * dy).sqrt();
    }
    let total = arc[arc.len() - 1];
    let tool = held.tool.clone();
    let rb = (tool.hair_radius() * s).max(0.55);
    let full = held.full();
    let step = rb.max(1.25);
    let nsteps = ((total / step).ceil() as usize).max(1);
    let bend_len = tool.length * (0.25 + 0.75 * (1.0 - tool.stiffness));

    for b in &mut held.bristles {
        b.prev = [None, None];
        b.bend = (0.0, 0.0);
    }
    let mut seg = 0usize;
    let mut last_dir = (1.0f32, 0.0f32);
    for k in 0..=nsteps {
        let d = (k as f32 * step).min(total);
        while seg + 1 < path.len() - 1 && arc[seg + 1] < d {
            seg += 1;
        }
        let seg_len = (arc[seg + 1] - arc[seg]).max(1e-6);
        let f = ((d - arc[seg]) / seg_len).clamp(0.0, 1.0);
        let (ax, ay) = path[seg];
        let (bx, by) = path[seg + 1];
        let hx = ax + (bx - ax) * f;
        let hy = ay + (by - ay) * f;
        let dir = if seg_len > 1e-3 { ((bx - ax) / seg_len, (by - ay) / seg_len) } else { last_dir };
        last_dir = dir;
        // the hand is never exact: the path drifts sideways a little and the
        // pressure breathes, both slowly along the stroke
        let lw = (tool.width * 2.5 + 6.0) * s;
        let hs = id as u64 * 7919;
        let off = g.shake * (0.05 * tool.width + 0.12) * s * (wander(d / lw, hs + 1) + 0.5 * wander(d / (lw * 0.37), hs + 2));
        let (hx, hy) = (hx - dir.1 * off, hy + dir.0 * off);
        let u = if total > 0.0 { d / total } else { 0.5 };
        let p = (g.pressure_at(u) * (1.0 + g.shake * 0.14 * wander(d / (lw * 0.8), hs + 3))).clamp(0.0, 1.0);
        let theta = match g.orient {
            Orient::Across => dir.1.atan2(dir.0) + std::f32::consts::FRAC_PI_2,
            Orient::Along => dir.1.atan2(dir.0),
            Orient::Fixed(a) => a,
        };
        let (st, ct) = theta.sin_cos();
        let half = tool.width * 0.5 * s * (0.45 + 0.55 * p) * (1.0 + tool.splay * (p - 0.5));
        let rate = 1.0 - (-(step / s) / (bend_len + 1e-3)).exp();

        for b in held.bristles.iter_mut() {
            let reach = (p - b.thresh) / (1.0 - b.thresh).max(1e-3);
            if reach <= 0.0 {
                b.prev = [None, None];
                continue;
            }
            // bristles wander a little across the stroke
            let wv = wander(d / s / tool.width.max(2.0) * 1.3, b.seed) * tool.ragged;
            let (ox, oy) = ((b.rx + wv * 0.12) * half, (b.ry + wv * 0.05) * half);
            let root = (hx + ox * ct - oy * st, hy + ox * st + oy * ct);
            // tips trail behind the motion and splay outward under pressure
            let trail = tool.length * s * b.len * p;
            let spread = tool.splay * p * 0.3;
            let target = (-dir.0 * trail + (ox * ct - oy * st) * spread, -dir.1 * trail + (ox * st + oy * ct) * spread);
            b.bend.0 += (target.0 - b.bend.0) * rate;
            b.bend.1 += (target.1 - b.bend.1) * rate;
            // one contact point: the belly-to-tip region of the bent bristle
            let cur = (root.0 + b.bend.0 * 0.6, root.1 + b.bend.1 * 0.6);
            let prev = b.prev[0].unwrap_or(cur);
            unsafe { exchange(sf, b, &tool, prev, cur, rb, reach, full, clip, id, scratch, &mut bounds) };
            b.prev[0] = Some(cur);
        }
    }
    bounds
}

/// Smooth 1-D value noise, −1..1.
fn wander(t: f32, seed: u64) -> f32 {
    let i = t.floor();
    let f = t - i;
    let f = f * f * (3.0 - 2.0 * f);
    let a = crate::rng::hash2(i as i64, 0, seed);
    let b = crate::rng::hash2(i as i64 + 1, 0, seed);
    (a + (b - a) * f) * 2.0 - 1.0
}

/// Paint exchange between one bristle and the canvas along the capsule
/// swept from `a` to `b` (pixels).
#[allow(clippy::too_many_arguments)]
unsafe fn exchange(
    sf: Surf,
    br: &mut Bristle,
    tool: &Tool,
    a: (f32, f32),
    b: (f32, f32),
    rb: f32,
    reach: f32,
    full: f32,
    clip: Option<&Mask>,
    id: u32,
    wts: &mut Vec<f32>,
    bounds: &mut Bounds,
) {
    unsafe {
        let (w, h) = (sf.w, sf.h);
        let s = sf.scale;
        let px_area = 1.0 / (s * s);
        let x0 = ((a.0.min(b.0) - rb - 1.0).floor().max(0.0)) as usize;
        let y0 = ((a.1.min(b.1) - rb - 1.0).floor().max(0.0)) as usize;
        let x1 = ((a.0.max(b.0) + rb + 1.0).ceil().max(0.0) as usize).min(w);
        let y1 = ((a.1.max(b.1) + rb + 1.0).ceil().max(0.0) as usize).min(h);
        if x1 <= x0 || y1 <= y0 {
            return;
        }
        let (dx, dy) = (b.0 - a.0, b.1 - a.1);
        let seg2 = dx * dx + dy * dy;
        let seg = seg2.sqrt();
        let (mx, my) = if seg > 1e-4 { (dx / seg, dy / seg) } else { (0.0, 0.0) };
        let (nx, ny) = (-my, mx);
        // lowest surface height this bristle reaches down to
        let th = 1.0 - reach * 1.6;

        // pass 1: contact weights
        let bw = x1 - x0;
        wts.clear();
        wts.resize(bw * (y1 - y0), 0.0);
        let mut sum_w = 0.0f32;
        let mut sum_cov = 0.0f32;
        for y in y0..y1 {
            for x in x0..x1 {
                let (px, py) = (x as f32 + 0.5, y as f32 + 0.5);
                let t = if seg2 > 1e-8 { (((px - a.0) * dx + (py - a.1) * dy) / seg2).clamp(0.0, 1.0) } else { 0.0 };
                let (qx, qy) = (a.0 + dx * t - px, a.1 + dy * t - py);
                let dist = (qx * qx + qy * qy).sqrt();
                if dist > rb + 0.5 {
                    continue;
                }
                let cov = 1.0 - smoothstep(rb * 0.5, rb + 0.5, dist);
                sum_cov += cov;
                let i = y * w + x;
                let surf = (*sf.base.add(i) + 0.35 * *sf.vol.add(i)).min(1.5);
                // soft hair bends down into the valleys of the weave; stiff hog
                // bristles ride on the peaks
                let give = 0.15 + 0.45 * (1.0 - tool.stiffness).clamp(0.0, 1.0);
                let contact = smoothstep(th - give, th + 0.2, surf);
                let mut wt = cov * contact;
                if let Some(m) = clip {
                    wt *= m.data[i];
                }
                wts[(y - y0) * bw + (x - x0)] = wt;
                sum_w += wt;
            }
        }
        if sum_w <= 1e-6 {
            return;
        }

        // deposit: a share of the load, proportional to distance traveled
        let travel = (seg / s).max(rb / s * 0.5);
        // only the part of the footprint actually in contact takes paint: a
        // bristle skimming the weave peaks keeps most of its load
        let touch = (sum_w / sum_cov.max(1e-6)).min(1.0);
        let dep_total = br.vol * (1.0 - (-travel / tool.run).exp()) * touch;
        let dep_per_w = dep_total / sum_w / px_area;
        // film splitting: a bristle in wet paint always lifts some of it, even
        // when loaded; a spent bristle drinks more
        let hunger = 0.35 + 0.65 * (1.0 - br.vol / full).clamp(0.0, 1.0).powf(1.5);
        let push_k = tool.push * (seg / (2.0 * rb)).clamp(0.0, 1.0);
        let off = rb + 1.0;

        let mut got_v = 0.0f32;
        let mut got_l = [0.0f32; LAT];
        let mut got_h: Prop = [0.0, 0.0];
        let (blat, bhide) = (br.lat, br.hide);
        for y in y0..y1 {
            for x in x0..x1 {
                let wt = wts[(y - y0) * bw + (x - x0)];
                if wt <= 0.0 {
                    continue;
                }
                let i = y * w + x;
                let vol = &mut *sf.vol.add(i);
                // one stroke lifts only part of the film
                if *sf.touched.add(i) != id {
                    *sf.touched.add(i) = id;
                    *sf.floor.add(i) = *vol * (1.0 - tool.pickup);
                }
                let v = *vol;
                if v > 1e-6 {
                    let own = if *sf.stroke.add(i) == id { 0.15 } else { 1.0 };
                    let take = (v * tool.pickup * wt * hunger * own).min((v - *sf.floor.add(i)).max(0.0));
                    if take > 0.0 {
                        *vol -= take;
                        let tv = take * px_area;
                        got_v += tv;
                        let l = &*sf.lat.add(i);
                        for k in 0..LAT {
                            got_l[k] += l[k] * tv;
                        }
                        let hp = *sf.hide.add(i);
                        got_h[0] += hp[0] * tv;
                        got_h[1] += hp[1] * tv;
                    }
                }
                if dep_per_w > 0.0 {
                    sf.add(i, dep_per_w * wt, &blat, bhide);
                    *sf.stroke.add(i) = id;
                }
                // plough: move paint outward from the bristle's path, and ahead
                if push_k > 0.0 {
                    let v = *sf.vol.add(i);
                    let m = v * push_k * wt;
                    if m > 1e-6 {
                        let (px, py) = (x as f32 + 0.5, y as f32 + 0.5);
                        let side = if (px - a.0) * nx + (py - a.1) * ny >= 0.0 { 1.0 } else { -1.0 };
                        let tx = px + (nx * side * 0.75 + mx * 0.45) * off;
                        let ty = py + (ny * side * 0.75 + my * 0.45) * off;
                        if tx >= 0.0 && ty >= 0.0 && (tx as usize) < w && (ty as usize) < h {
                            let j = ty as usize * w + tx as usize;
                            // a clipped stroke can't push paint past its mask:
                            // only the accepted share moves, the rest stays
                            let m = m * clip.map_or(1.0, |c| c.data[j]);
                            if j != i && m > 0.0 {
                                let l = *sf.lat.add(i);
                                let hd = *sf.hide.add(i);
                                *sf.vol.add(i) -= m;
                                sf.add(j, m, &l, hd);
                            }
                        }
                    }
                }
            }
        }
        br.vol = (br.vol - dep_total).max(0.0);
        if got_v > 0.0 {
            for k in 0..LAT {
                got_l[k] /= got_v;
            }
            got_h[0] /= got_v;
            got_h[1] /= got_v;
            mix_into(&mut br.vol, &mut br.lat, &mut br.hide, got_v, &got_l, got_h);
        }
        let pad = (off + 2.0) as usize;
        grow(bounds, x0.saturating_sub(pad), y0.saturating_sub(pad), (x1 + pad).min(w), (y1 + pad).min(h));
    }
}

//! The painting surface: color, paint relief and the woven support.

use crate::color::{self, Rgb};
use crate::mask::Mask;
use crate::pigment::Pigment;
use crate::rng::hash2;
use crate::surface::{COAT_UM, Linen, vnoise};

/// Fraction of a glaze layer that stays as film (the rest of the "thickness"
/// is how deep the color reads; a glaze is mostly medium, and thin).
const GLAZE_FILM: f32 = 0.3;
use crate::smoothstep;
use rayon::prelude::*;

/// Pixel dimensions plus the units → pixels scale.
#[derive(Clone, Copy, Debug)]
pub struct Frame {
    pub w: usize,
    pub h: usize,
    /// Pixels per unit.
    pub scale: f32,
}

impl Frame {
    pub const WIDTH_UNITS: f32 = 1000.0;

    pub fn width(&self) -> f32 {
        Self::WIDTH_UNITS
    }
    pub fn height(&self) -> f32 {
        self.h as f32 / self.scale
    }
    /// Pixel index for a point in units (clamped).
    #[inline]
    pub fn index(&self, x: f32, y: f32) -> usize {
        let px = ((x * self.scale) as isize).clamp(0, self.w as isize - 1) as usize;
        let py = ((y * self.scale) as isize).clamp(0, self.h as isize - 1) as usize;
        py * self.w + px
    }
}

pub struct Canvas {
    pub(crate) f: Frame,
    /// Linear RGB reflectance, row major.
    pub(crate) px: Vec<Rgb>,
    /// Physical surface height, µm: woven linen, ground layers, paint films.
    pub(crate) height: Vec<f32>,
    /// Accumulated paint film in coats (bookkeeping).
    pub(crate) film: Vec<f32>,
    pub(crate) linen: Option<Linen>,
    /// Physical size: millimeters per unit (the canvas is 1000 units wide).
    pub(crate) mm_per_unit: f32,
    /// Wet paint on top of the dry picture.
    pub(crate) wet: crate::wet::Wet,
    /// Bumped whenever the height changes; `base` caches the surface relief
    /// bristles feel.
    pub(crate) surf_gen: u64,
    pub(crate) base: Option<(u64, Vec<f32>)>,
}

impl Canvas {
    /// `aspect` = width / height.
    pub fn new(width_px: usize, aspect: f32, ground: Rgb) -> Self {
        let h = (width_px as f32 / aspect).round() as usize;
        let f = Frame { w: width_px, h, scale: width_px as f32 / Frame::WIDTH_UNITS };
        let n = width_px * h;
        Canvas {
            f,
            px: vec![ground; n],
            height: vec![0.0; n],
            film: vec![0.0; n],
            linen: None,
            mm_per_unit: 0.7,
            wet: crate::wet::Wet::new(n),
            surf_gen: 0,
            base: None,
        }
    }

    /// Physical width of the painting in mm (default 700).
    pub fn with_size_mm(mut self, width_mm: f32) -> Self {
        self.mm_per_unit = width_mm / Frame::WIDTH_UNITS;
        self.build_support();
        self
    }

    /// Use a woven linen support.
    pub fn with_linen(mut self, l: Linen) -> Self {
        self.linen = Some(l);
        self.build_support();
        self
    }

    /// A ground layer over the whole canvas: `um` µm of paint of `color` and
    /// `hiding`, spread with a knife or broad brush, leveled and set.
    /// `stiff` 0..1 is its body (fluid chalk-glue ≈ 0.2, oil lead white ≈ 0.6);
    /// `texture` 0..1 roughens it before it levels (a roller or scraped knife).
    pub fn prime(&mut self, color: Rgb, hiding: f32, um: f32, stiff: f32, texture: f32, seed: u64) {
        self.dry();
        let (w, h) = (self.f.w, self.f.h);
        let px = self.px_mm();
        let add: Vec<f32> = (0..w * h)
            .into_par_iter()
            .map(|i| {
                let (x, y) = ((i % w) as f32 * px, (i / w) as f32 * px);
                let n = 0.65 * vnoise(x / 0.3, y / 0.3, seed) + 0.35 * vnoise(x / 0.9, y / 0.9, seed + 1) - 0.5;
                um * (1.0 + texture * 1.4 * n).max(0.0)
            })
            .collect();
        let sv = vec![stiff; w * h];
        let t = self.settle((0, 0, w, h), &add, &sv);
        let pig = Pigment::with_hiding(color, hiding);
        self.px.par_iter_mut().zip(&t).for_each(|(p, &ti)| *p = pig.over(*p, ti / COAT_UM));
        self.film.par_iter_mut().zip(&t).for_each(|(f, &ti)| *f += ti / COAT_UM);
    }

    /// Pixel dimensions and scale (for building masks).
    pub fn frame(&self) -> Frame {
        self.f
    }

    /// Linear RGB pixels (read-only).
    pub fn pixels(&self) -> &[Rgb] {
        &self.px
    }

    /// Surface height in µm (read-only). Edit it through canvas operations
    /// so derived data (the brushes' contact surface) stays in sync.
    pub fn surface_um(&self) -> &[f32] {
        &self.height
    }

    /// Panics unless `m` was made for this canvas's frame.
    #[track_caller]
    pub(crate) fn check_mask(&self, m: &Mask) {
        assert!(
            m.f.w == self.f.w && m.f.h == self.f.h && m.data.len() == self.f.w * self.f.h,
            "mask {}x{} does not match canvas {}x{}",
            m.f.w,
            m.f.h,
            self.f.w,
            self.f.h
        );
    }

    /// Canvas width in units (always 1000).
    pub fn width(&self) -> f32 {
        self.f.width()
    }
    /// Canvas height in units.
    pub fn height(&self) -> f32 {
        self.f.height()
    }

    /// Current color at a point in units.
    #[inline]
    pub fn sample(&self, x: f32, y: f32) -> Rgb {
        self.px[self.f.index(x, y)]
    }

    /// Per-pixel transform; `g(x, y, current) -> new`, x/y in units.
    pub fn apply(&mut self, g: impl Fn(f32, f32, Rgb) -> Rgb + Sync) {
        let inv = 1.0 / self.f.scale;
        self.px.par_chunks_mut(self.f.w).enumerate().for_each(|(y, row)| {
            let yu = (y as f32 + 0.5) * inv;
            for (x, p) in row.iter_mut().enumerate() {
                *p = g((x as f32 + 0.5) * inv, yu, *p);
            }
        });
    }

    /// Like `apply`, but only where `m` > 0; `g` receives the coverage.
    pub fn apply_masked(&mut self, m: &Mask, g: impl Fn(f32, f32, Rgb, f32) -> Rgb + Sync) {
        self.check_mask(m);
        let inv = 1.0 / self.f.scale;
        let w = self.f.w;
        self.px.par_chunks_mut(w).enumerate().for_each(|(y, row)| {
            let yu = (y as f32 + 0.5) * inv;
            let mrow = &m.data[y * w..(y + 1) * w];
            for (x, p) in row.iter_mut().enumerate() {
                let c = mrow[x];
                if c > 0.0 {
                    *p = g((x as f32 + 0.5) * inv, yu, *p, c);
                }
            }
        });
    }

    /// Kubelka–Munk glaze: a layer of `pigment` whose thickness is
    /// `thickness(x, y)` (times mask coverage, if given).
    pub fn glaze(
        &mut self,
        pigment: &Pigment,
        mask: Option<&Mask>,
        thickness: impl Fn(f32, f32) -> f32 + Sync,
    ) {
        if let Some(m) = mask {
            self.check_mask(m);
        }
        self.dry();
        // the glaze is mostly medium: a thin fluid film that levels and pools
        // in the hollows of the surface, so it is deeper there
        let (w, h) = (self.f.w, self.f.h);
        let inv = 1.0 / self.f.scale;
        let th: Vec<f32> = (0..w * h)
            .into_par_iter()
            .map(|i| {
                let c = mask.map_or(1.0, |m| m.data[i]);
                if c <= 0.0 { 0.0 } else { thickness(((i % w) as f32 + 0.5) * inv, ((i / w) as f32 + 0.5) * inv).max(0.0) * c }
            })
            .collect();
        let add: Vec<f32> = th.iter().map(|t| t * COAT_UM * GLAZE_FILM).collect();
        let sv = vec![0.05f32; w * h];
        let t = self.settle((0, 0, w, h), &add, &sv);
        self.px.par_iter_mut().enumerate().for_each(|(i, p)| {
            if add[i] > 0.0 {
                *p = pigment.over(*p, th[i] * t[i] / add[i]);
            }
        });
        self.film.par_iter_mut().zip(&t).for_each(|(f, &ti)| *f += ti / COAT_UM);
    }

    /// Age cracks (craquelure): an irregular network of fine cracks, cell size
    /// in units. Darkens slightly and cuts grooves into the relief.
    pub fn craquelure(&mut self, cell: f32, strength: f32, seed: u64) {
        let warp = crate::noise::Fbm::new(seed as u32 + 77, 4, cell * 3.0);
        // where the paint film cracked: patchy, not uniform
        let cluster = crate::noise::Fbm::new(seed as u32 + 78, 3, cell * 12.0);
        let width = 0.012 * cell; // hairline, in units
        let inv = 1.0 / self.f.scale;
        let aa = 0.8 * inv; // ~1px antialias
        let w = self.f.w;
        let mut cracks = vec![0.0f32; w * self.f.h];
        cracks.par_chunks_mut(w).enumerate().for_each(|(y, row)| {
            let yu = (y as f32 + 0.5) * inv;
            for (x, out) in row.iter_mut().enumerate() {
                let xu = (x as f32 + 0.5) * inv;
                let wx = xu + warp.get(xu, yu) * cell * 0.3;
                let wy = yu + warp.get(xu + 91.0, yu - 37.0) * cell * 0.3;
                // a crack thinner than a pixel covers only part of it
                let line = |e: f32, wd: f32| {
                    let wp = wd.max(aa);
                    (1.0 - smoothstep(wp * 0.5 - aa * 0.5, wp * 0.5 + aa * 0.5, e)) * (wd / wp)
                };
                // main network, stretched a bit horizontally like canvas cracks
                let (e1, a1, b1) = voronoi_edge(wx / (cell * 1.25), wy / cell, seed);
                // each crack segment (cell pair) gets its own strength; many are faint
                let seg1 = hash2(a1.min(b1), a1.max(b1), seed + 5).powf(1.8);
                let c1 = line(e1 * cell, width) * seg1;
                // finer secondary cracks inside cells, mostly faint
                let (e2, a2, b2) = voronoi_edge(wx / (cell * 0.45), wy / (cell * 0.4), seed + 9);
                let seg2 = hash2(a2.min(b2), a2.max(b2), seed + 6).powf(3.0) * 0.6;
                let c2 = line(e2 * cell * 0.4, width * 0.7) * seg2;
                let k = smoothstep(-0.3, 0.4, cluster.get(xu, yu));
                *out = c1.max(c2) * (0.25 + 0.75 * k);
            }
        });
        let s = strength;
        self.px.par_iter_mut().zip(&cracks).for_each(|(p, c)| {
            let k = 1.0 - s * c;
            *p = [p[0] * k, p[1] * k, p[2] * k];
        });
        self.surf_gen += 1;
        self.height.par_iter_mut().zip(&cracks).for_each(|(h, c)| *h -= c * 8.0);
    }

    /// Light the surface relief (paint ridges + weave) from the upper left.
    /// `strength` ≈ 0.3–1.0; `gloss` adds a faint varnish sheen on ridges.
    pub fn relief(&mut self, strength: f32, gloss: f32) {
        self.dry();
        let (w, h) = (self.f.w, self.f.h);
        let surf = &self.height;
        // light from the upper left at ~35° elevation
        let l = {
            let v = [-0.58f32, -0.58, 0.57];
            let n = (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt();
            [v[0] / n, v[1] / n, v[2] / n]
        };
        // true slopes: µm of height per µm across (central difference)
        let k = 0.5 / (self.px_mm() * 1000.0);
        self.px.par_chunks_mut(w).enumerate().for_each(|(y, row)| {
            for x in 0..w {
                let at = |xx: usize, yy: usize| surf[yy.min(h - 1) * w + xx.min(w - 1)];
                let dx = (at(x + 1, y) - at(x.saturating_sub(1), y)) * k;
                let dy = (at(x, y + 1) - at(x, y.saturating_sub(1))) * k;
                // paint edges round over: soft-limit the slope so a hairline
                // ridge doesn't shade to black on one side and white on the other
                let g = (dx * dx + dy * dy).sqrt();
                let lim = 1.0 / (1.0 + g / 1.2);
                let (dx, dy) = (dx * lim, dy * lim);
                let n = {
                    let v = [-dx, -dy, 1.0];
                    let m = (v[0] * v[0] + v[1] * v[1] + 1.0).sqrt();
                    [v[0] / m, v[1] / m, v[2] / m]
                };
                let ndl = n[0] * l[0] + n[1] * l[1] + n[2] * l[2];
                let shade = 1.0 + strength * (ndl / l[2] - 1.0);
                // Blinn-Phong sheen, view straight on
                let hv = [l[0], l[1], l[2] + 1.0];
                let hm = (hv[0] * hv[0] + hv[1] * hv[1] + hv[2] * hv[2]).sqrt();
                let ndh = ((n[0] * hv[0] + n[1] * hv[1] + n[2] * hv[2]) / hm).max(0.0);
                let flat = (l[2] + 1.0) / hm;
                let spec = (gloss * (ndh.powf(60.0) - flat.powf(60.0)).max(0.0)).min(gloss * 0.2);
                let p = &mut row[x];
                for c in 0..3 {
                    p[c] = (p[c] * shade + spec).max(0.0);
                }
            }
        });
    }

    /// Save as an 8-bit sRGB PNG with triangular dither (prevents banding in
    /// the long, subtle gradients Friedrich loves).
    pub fn save(&mut self, path: impl AsRef<std::path::Path>) -> std::io::Result<()> {
        self.dry();
        let (w, h) = (self.f.w, self.f.h);
        let mut buf = vec![0u8; w * h * 3];
        buf.par_chunks_mut(w * 3).enumerate().for_each(|(y, row)| {
            for x in 0..w {
                let p = self.px[y * w + x];
                for c in 0..3 {
                    let d = hash2(x as i64, y as i64, c as u64 * 7 + 1)
                        - hash2(x as i64, y as i64, c as u64 * 7 + 2);
                    let v = color::linear_to_srgb(p[c]) * 255.0 + d;
                    row[x * 3 + c] = v.round().clamp(0.0, 255.0) as u8;
                }
            }
        });
        if let Some(dir) = path.as_ref().parent() {
            std::fs::create_dir_all(dir)?;
        }
        image::save_buffer(path.as_ref(), &buf, w as u32, h as u32, image::ColorType::Rgb8)
            .map_err(std::io::Error::other)
    }
}


/// Distance to the nearest Voronoi cell border (F2 - F1)/2, in cell units,
/// plus ids of the two nearest cells (identifies the crack segment).
fn voronoi_edge(x: f32, y: f32, seed: u64) -> (f32, i64, i64) {
    let (ix, iy) = (x.floor() as i64, y.floor() as i64);
    let (mut d1, mut d2) = (f32::MAX, f32::MAX);
    let (mut id1, mut id2) = (0i64, 0i64);
    for j in -1..=1 {
        for i in -1..=1 {
            let (cx, cy) = (ix + i, iy + j);
            let px = cx as f32 + hash2(cx, cy, seed);
            let py = cy as f32 + hash2(cx, cy, seed + 101);
            let d = ((px - x).powi(2) + (py - y).powi(2)).sqrt();
            let id = cx.wrapping_mul(73_856_093) ^ cy.wrapping_mul(19_349_663);
            if d < d1 {
                d2 = d1;
                id2 = id1;
                d1 = d;
                id1 = id;
            } else if d < d2 {
                d2 = d;
                id2 = id;
            }
        }
    }
    ((d2 - d1) * 0.5, id1, id2)
}

