//! Float coverage masks the size of the canvas.

use crate::canvas::Frame;
use crate::noise::Fbm;
use crate::shape::Shape;
use rayon::prelude::*;

#[derive(Clone)]
pub struct Mask {
    pub f: Frame,
    pub data: Vec<f32>,
}

impl Mask {
    pub fn empty(f: Frame) -> Self {
        Mask { f, data: vec![0.0; f.w * f.h] }
    }

    pub fn full(f: Frame) -> Self {
        Mask { f, data: vec![1.0; f.w * f.h] }
    }

    /// Evaluate `g(x, y)` (units) at every pixel center.
    pub fn from_fn(f: Frame, g: impl Fn(f32, f32) -> f32 + Sync) -> Self {
        let mut data = vec![0.0; f.w * f.h];
        let inv = 1.0 / f.scale;
        data.par_chunks_mut(f.w).enumerate().for_each(|(y, row)| {
            let yu = (y as f32 + 0.5) * inv;
            for (x, v) in row.iter_mut().enumerate() {
                *v = g((x as f32 + 0.5) * inv, yu);
            }
        });
        Mask { f, data }
    }

    /// Antialiased fill of a shape.
    pub fn from_shape(f: Frame, shape: Shape) -> Self {
        let mut m = Mask::empty(f);
        let paths = shape.paths();
        if !paths.is_empty() {
            let mut tm = tiny_skia::Mask::new(f.w as u32, f.h as u32).unwrap();
            for path in &paths {
                tm.fill_path(
                    path,
                    tiny_skia::FillRule::Winding,
                    true,
                    tiny_skia::Transform::from_scale(f.scale, f.scale),
                );
            }
            for (d, s) in m.data.iter_mut().zip(tm.data()) {
                *d = *s as f32 / 255.0;
            }
        }
        m
    }

    /// Approximate Gaussian blur (3 box passes). `radius` in units.
    pub fn blur(mut self, radius: f32) -> Self {
        let r = (radius * self.f.scale / 1.7).round() as usize;
        if r == 0 {
            return self;
        }
        for _ in 0..3 {
            box_rows(&mut self.data, self.f.w, r);
            let mut t = transpose(&self.data, self.f.w, self.f.h);
            box_rows(&mut t, self.f.h, r);
            self.data = transpose(&t, self.f.h, self.f.w);
        }
        self
    }

    /// Break up the edge with noise: the 0.5 contour gets pushed around by
    /// `amount` (0..1) of fbm at the given period, then re-sharpened to `edge` softness.
    pub fn roughen(mut self, seed: u32, period: f32, amount: f32, edge: f32) -> Self {
        let n = Fbm::new(seed, 5, period);
        let inv = 1.0 / self.f.scale;
        let w = self.f.w;
        self.data.par_chunks_mut(w).enumerate().for_each(|(y, row)| {
            let yu = (y as f32 + 0.5) * inv;
            for (x, v) in row.iter_mut().enumerate() {
                let d = *v + n.get((x as f32 + 0.5) * inv, yu) * amount;
                *v = crate::smoothstep(0.5 - edge, 0.5 + edge, d);
            }
        });
        self
    }

    pub fn map(mut self, g: impl Fn(f32) -> f32 + Sync) -> Self {
        self.data.par_iter_mut().for_each(|v| *v = g(*v));
        self
    }

    /// Multiply by a function of position.
    pub fn mul_fn(mut self, g: impl Fn(f32, f32) -> f32 + Sync) -> Self {
        let inv = 1.0 / self.f.scale;
        let w = self.f.w;
        self.data.par_chunks_mut(w).enumerate().for_each(|(y, row)| {
            let yu = (y as f32 + 0.5) * inv;
            for (x, v) in row.iter_mut().enumerate() {
                *v *= g((x as f32 + 0.5) * inv, yu);
            }
        });
        self
    }

    pub fn mul(mut self, o: &Mask) -> Self {
        self.data.par_iter_mut().zip(&o.data).for_each(|(a, b)| *a *= b);
        self
    }

    pub fn union(mut self, o: &Mask) -> Self {
        self.data.par_iter_mut().zip(&o.data).for_each(|(a, b)| *a = a.max(*b));
        self
    }

    pub fn subtract(mut self, o: &Mask) -> Self {
        self.data.par_iter_mut().zip(&o.data).for_each(|(a, b)| *a *= 1.0 - b);
        self
    }

    pub fn invert(self) -> Self {
        self.map(|v| 1.0 - v)
    }

    #[inline]
    pub fn at(&self, i: usize) -> f32 {
        self.data[i]
    }
}

fn box_rows(data: &mut [f32], w: usize, r: usize) {
    data.par_chunks_mut(w).for_each(|row| {
        let src = row.to_vec();
        let mut acc = 0.0f32;
        let n = (2 * r + 1) as f32;
        // clamp-to-edge
        let get = |i: isize| src[i.clamp(0, w as isize - 1) as usize];
        for i in -(r as isize)..=(r as isize) {
            acc += get(i);
        }
        for x in 0..w {
            row[x] = acc / n;
            acc += get(x as isize + r as isize + 1) - get(x as isize - r as isize);
        }
    });
}

fn transpose(src: &[f32], w: usize, h: usize) -> Vec<f32> {
    let mut dst = vec![0.0; w * h];
    dst.par_chunks_mut(h).enumerate().for_each(|(x, col)| {
        for y in 0..h {
            col[y] = src[y * w + x];
        }
    });
    dst
}
//! Vector shapes in canvas units (rasterized by tiny-skia into masks).

use tiny_skia::{Path, PathBuilder};

#[derive(Default)]
pub struct Shape {
    pb: PathBuilder,
    /// Independently filled parts (their windings never cancel each other).
    parts: Vec<Path>,
}

impl Shape {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn move_to(mut self, x: f32, y: f32) -> Self {
        self.pb.move_to(x, y);
        self
    }
    pub fn line_to(mut self, x: f32, y: f32) -> Self {
        self.pb.line_to(x, y);
        self
    }
    pub fn quad_to(mut self, cx: f32, cy: f32, x: f32, y: f32) -> Self {
        self.pb.quad_to(cx, cy, x, y);
        self
    }
    pub fn cubic_to(mut self, c1: (f32, f32), c2: (f32, f32), p: (f32, f32)) -> Self {
        self.pb.cubic_to(c1.0, c1.1, c2.0, c2.1, p.0, p.1);
        self
    }
    pub fn close(mut self) -> Self {
        self.pb.close();
        self
    }

    pub fn rect(mut self, x: f32, y: f32, w: f32, h: f32) -> Self {
        if let Some(r) = tiny_skia::Rect::from_xywh(x, y, w, h) {
            self.pb.push_rect(r);
        }
        self
    }

    pub fn ellipse(mut self, cx: f32, cy: f32, rx: f32, ry: f32) -> Self {
        if let Some(r) = tiny_skia::Rect::from_xywh(cx - rx, cy - ry, 2.0 * rx, 2.0 * ry) {
            self.pb.push_oval(r);
        }
        self
    }

    pub fn circle(self, cx: f32, cy: f32, r: f32) -> Self {
        self.ellipse(cx, cy, r, r)
    }

    /// Straight-edged closed polygon.
    pub fn poly(mut self, pts: &[(f32, f32)]) -> Self {
        if let Some((&(x, y), rest)) = pts.split_first() {
            self.pb.move_to(x, y);
            for &(x, y) in rest {
                self.pb.line_to(x, y);
            }
            self.pb.close();
        }
        self
    }

    /// Closed smooth curve through the points (Catmull-Rom → cubic Béziers).
    pub fn smooth_poly(mut self, pts: &[(f32, f32)]) -> Self {
        let n = pts.len();
        if n < 3 {
            return self.poly(pts);
        }
        self.pb.move_to(pts[0].0, pts[0].1);
        for i in 0..n {
            let p0 = pts[(i + n - 1) % n];
            let p1 = pts[i];
            let p2 = pts[(i + 1) % n];
            let p3 = pts[(i + 2) % n];
            let c1 = (p1.0 + (p2.0 - p0.0) / 6.0, p1.1 + (p2.1 - p0.1) / 6.0);
            let c2 = (p2.0 - (p3.0 - p1.0) / 6.0, p2.1 - (p3.1 - p1.1) / 6.0);
            self.pb.cubic_to(c1.0, c1.1, c2.0, c2.1, p2.0, p2.1);
        }
        self.pb.close();
        self
    }

    /// Region below an open curve (e.g. a hill line or horizon) down to `bottom`.
    pub fn below(mut self, curve: &[(f32, f32)], bottom: f32) -> Self {
        if curve.len() < 2 {
            return self;
        }
        self.pb.move_to(curve[0].0, bottom);
        for &(x, y) in curve {
            self.pb.line_to(x, y);
        }
        self.pb.line_to(curve[curve.len() - 1].0, bottom);
        self.pb.close();
        self
    }

    /// A tapered band along a polyline: `widths[i]` is the full width at
    /// `pts[i]`. Built from per-segment quads plus round joints, each filled
    /// on its own, so sharp bends never leave holes.
    pub fn ribbon(mut self, pts: &[(f32, f32)], widths: &[f32]) -> Self {
        let n = pts.len();
        if n < 2 {
            return self;
        }
        let wid = |i: usize| widths[i.min(widths.len() - 1)] * 0.5;
        for i in 0..n - 1 {
            let (a, b) = (pts[i], pts[i + 1]);
            let (dx, dy) = (b.0 - a.0, b.1 - a.1);
            let l = (dx * dx + dy * dy).sqrt();
            if l < 1e-4 {
                continue;
            }
            let (nx, ny) = (-dy / l, dx / l);
            let (ha, hb) = (wid(i), wid(i + 1));
            let mut pb = PathBuilder::new();
            pb.move_to(a.0 + nx * ha, a.1 + ny * ha);
            pb.line_to(b.0 + nx * hb, b.1 + ny * hb);
            pb.line_to(b.0 - nx * hb, b.1 - ny * hb);
            pb.line_to(a.0 - nx * ha, a.1 - ny * ha);
            pb.close();
            if let Some(p) = pb.finish() {
                self.parts.push(p);
            }
        }
        for i in 0..n {
            let hw = wid(i);
            if hw > 0.03 {
                if let Some(p) = PathBuilder::from_circle(pts[i].0, pts[i].1, hw) {
                    self.parts.push(p);
                }
            }
        }
        self
    }

    /// Merge another shape's parts into this one (filled independently).
    pub fn add(mut self, other: Shape) -> Self {
        self.parts.extend(other.paths());
        self
    }

    /// All independently filled paths.
    pub fn paths(self) -> Vec<Path> {
        let mut v = self.parts;
        if let Some(p) = self.pb.finish() {
            v.push(p);
        }
        v
    }

    pub fn path(self) -> Option<Path> {
        self.pb.finish()
    }
}
//! Path geometry shared by the brushes.

/// Catmull-Rom resample so consecutive points are ~2px apart.
pub(crate) fn densify(p: &[(f32, f32)]) -> Vec<(f32, f32)> {
    let n = p.len();
    let mut out = Vec::new();
    for i in 0..n - 1 {
        let p0 = p[i.saturating_sub(1)];
        let p1 = p[i];
        let p2 = p[i + 1];
        let p3 = p[(i + 2).min(n - 1)];
        let len = ((p2.0 - p1.0).powi(2) + (p2.1 - p1.1).powi(2)).sqrt();
        let k = ((len / 2.0).ceil() as usize).max(1);
        for j in 0..k {
            let t = j as f32 / k as f32;
            let (t2, t3) = (t * t, t * t * t);
            let cr = |a: f32, b: f32, c: f32, d: f32| {
                0.5 * (2.0 * b + (-a + c) * t + (2.0 * a - 5.0 * b + 4.0 * c - d) * t2
                    + (-a + 3.0 * b - 3.0 * c + d) * t3)
            };
            out.push((cr(p0.0, p1.0, p2.0, p3.0), cr(p0.1, p1.1, p2.1, p3.1)));
        }
    }
    out.push(p[n - 1]);
    out
}

//! Friedrich's small figures, written as brush gestures.
//!
//! Local coordinates: `u` across (+ = the figure's right, which is also the
//! viewer's right since they face away), `v` up from the feet, both in figure
//! heights. Sources for what they look like:
//! - Monk by the Sea: "a single figure, dressed in a long garment ... turned
//!   almost completely away from the viewer"; "the long blond hair and round
//!   skull" (https://en.wikipedia.org/wiki/The_Monk_by_the_Sea).
//! - Two Men Contemplating the Moon: "The man on the right is wearing a
//!   grey-green cape and the black beret of the altdeutsche Tracht and has a
//!   stick in his right hand. The man on the left is somewhat higher on the
//!   path and is leaning on his companion's shoulder; he is slimmer and is
//!   wearing a grey-green frock-coat, from which a white collar protrudes, and
//!   the black cap of an early Burschenschaft"
//!   (https://en.wikipedia.org/wiki/Two_Men_Contemplating_the_Moon).

use paint::{Canvas, Hand, Mark, Paint, Rgb, Tool};
use std::f32::consts::FRAC_PI_2;

fn body(color: Rgb) -> Paint {
    Paint { color, hiding: 0.97, stiff: 1.0 }
}

/// Thin paint for small touches (heads, caps, collars): no impasto knobs.
fn thin(color: Rgb) -> Paint {
    Paint { color, hiding: 0.95, stiff: 0.45 }
}

fn lean(color: Rgb) -> Paint {
    Paint { color, hiding: 0.55, stiff: 0.4 }
}

/// The monk: long dark habit widening a little to the hem, sloping shoulders,
/// right arm raised with the hand to the face (the elbow shows at his side),
/// round head of pale hair. `light` is a lean rim touched on the lit side.
pub fn monk(c: &mut Canvas, at: (f32, f32), size: f32, robe: Rgb, hair: Rgb, light: Option<Rgb>, seed: u64) {
    let mut h = Hand::new(at, size, seed);
    let p = body(robe);
    let mut b = h.take(Tool::round_sable, 0.075, p, 1.0);
    // the habit: four long strokes from the shoulders down, pressing harder
    // toward the hem so it widens; outer strokes lean out a little
    for (i, (u0, u1)) in [(-0.045f32, -0.075f32), (0.045, 0.08), (-0.014, -0.025), (0.016, 0.028)].iter().enumerate() {
        if i % 2 == 0 {
            b.reload(p, 1.0);
        }
        let mid = (u0 + u1) * 0.5 + h.rng.normal() * 0.004;
        h.mark(c, &mut b, Mark { pts: &[(*u0, 0.82), (mid, 0.45), (*u1, 0.02)], pressure: (0.65, 1.0), ramps: (0.05, 0.06) }, None);
    }
    // and over it once more, lighter, to close the grooves between the hairs
    for (u0, u1) in [(-0.03f32, -0.05f32), (0.03, 0.055), (0.0, 0.0)] {
        b.reload(p, 1.0);
        h.mark(c, &mut b, Mark { pts: &[(u0, 0.8), (u1, 0.03)], pressure: (0.6, 0.85), ramps: (0.1, 0.1) }, None);
    }
    b.reload(p, 1.0);
    // shoulders: one stroke across, dropping at both ends
    h.line(c, &mut b, &[(-0.085, 0.76), (-0.04, 0.825), (0.04, 0.825), (0.085, 0.76)], 0.7, 0.7);
    // raised right arm: out to the elbow and back in toward the face
    h.line(c, &mut b, &[(0.06, 0.79), (0.115, 0.69), (0.085, 0.61)], 0.75, 0.55);
    // hem: firm across the bottom
    h.line(c, &mut b, &[(-0.095, 0.03), (0.0, 0.015), (0.105, 0.03)], 0.8, 0.8);
    // the hood gathered at the nape
    let mut nb = h.take(Tool::round_sable, 0.04, p, 0.8);
    h.dab(c, &mut nb, 0.0, 0.845, 0.03, 0.0, 0.8);
    // let the habit set before the head goes on, so the hair stays clean
    c.dry();
    // the head: a dab of pale hair
    let mut hb = h.take(Tool::round_sable, 0.068, thin(hair), 1.0 * 0.45);
    h.dab(c, &mut hb, 0.004, 0.9, 0.065, FRAC_PI_2, 1.0);
    if let Some(l) = light {
        // light from the left: a lean touch dragged down the left edge,
        // barely pressing, and one along the left shoulder
        c.dry();
        let tone = paint::color::mix(robe, l, 0.4, paint::Mix::Pigment);
        let mut lb = h.take(Tool::round_sable, 0.025, lean(tone), 0.4 * 0.4);
        h.mark(c, &mut lb, Mark { pts: &[(-0.07, 0.75), (-0.074, 0.6), (-0.078, 0.45)], pressure: (0.35, 0.15), ramps: (0.15, 0.6) }, None);
        h.mark(c, &mut lb, Mark { pts: &[(-0.02, 0.83), (-0.06, 0.8)], pressure: (0.4, 0.3), ramps: (0.1, 0.4) }, None);
        h.dab(c, &mut lb, -0.02, 0.91, 0.03, FRAC_PI_2, 0.4);
    }
}

/// Trousers and boots, painted first so the coat can come down over them.
fn legs(c: &mut Canvas, h: &mut Hand, trousers: Rgb, dark: Rgb, gap: f32, w: f32) {
    let tr = body(trousers);
    let mut b = h.take(Tool::round_sable, w, tr, 1.0);
    for s in [-1.0f32, 1.0] {
        h.mark(c, &mut b, Mark { pts: &[(s * gap, 0.45), (s * gap, 0.2), (s * (gap + 0.002), 0.035)], pressure: (0.95, 0.65), ramps: (0.0, 0.05) }, None);
    }
    let mut bt = h.take(Tool::round_sable, w * 0.62, thin(dark), 1.0 * 0.45);
    for s in [-1.0f32, 1.0] {
        h.mark(c, &mut bt, Mark { pts: &[(s * (gap - 0.004), 0.02), (s * (gap + 0.024), 0.012)], pressure: (0.9, 0.6), ramps: (0.0, 0.3) }, None);
    }
    c.dry();
}

/// The older man in a cape and beret, stick in his right hand. Returns his
/// left shoulder in canvas units (for a companion's hand).
#[allow(clippy::too_many_arguments)]
pub fn man_in_cape(c: &mut Canvas, at: (f32, f32), size: f32, cape: Rgb, dark: Rgb, hair: Rgb, rim: Option<Rgb>, seed: u64) -> (f32, f32) {
    let mut h = Hand::new(at, size, seed);
    // back to front: legs, the stick, then the cape over them
    legs(c, &mut h, paint::color::mix(dark, cape, 0.3, paint::Mix::Pigment), dark, 0.03, 0.045);
    let mut st = h.take(Tool::rigger, 0.012, body(dark), 1.0);
    h.mark(c, &mut st, Mark { pts: &[(0.15, 0.52), (0.175, 0.26), (0.2, 0.0)], pressure: (0.9, 0.8), ramps: (0.0, 0.05) }, None);
    c.dry();
    // the cape: strokes fanning out from the neck, a bell to the knee
    let p = body(cape);
    let mut cb = h.take(Tool::round_sable, 0.07, p, 1.0);
    for (i, k) in [-3.0f32, 3.0, -2.0, 2.0, -1.0, 1.0, 0.0].iter().enumerate() {
        if i % 2 == 0 {
            cb.reload(p, 1.0);
        }
        let (u0, u1) = (k * 0.018, k * 0.045 + h.rng.normal() * 0.006);
        h.mark(c, &mut cb, Mark { pts: &[(u0, 0.83), ((u0 + u1) * 0.5, 0.6), (u1, 0.36)], pressure: (0.6, 1.0), ramps: (0.05, 0.1) }, None);
    }
    cb.reload(p, 1.0);
    h.line(c, &mut cb, &[(-0.105, 0.77), (-0.05, 0.835), (0.05, 0.835), (0.105, 0.77)], 0.75, 0.75);
    h.line(c, &mut cb, &[(-0.15, 0.37), (0.0, 0.355), (0.15, 0.37)], 0.7, 0.7);
    c.dry();
    // the hand on the stick
    let mut hb = h.take(Tool::round_sable, 0.035, thin(dark), 0.8 * 0.45);
    h.dab(c, &mut hb, 0.15, 0.5, 0.03, FRAC_PI_2, 0.9);
    // head, then the beret: a wide flat dab resting on it, tipped a little
    let mut hd = h.take(Tool::round_sable, 0.06, thin(hair), 1.0 * 0.45);
    h.dab(c, &mut hd, 0.0, 0.88, 0.05, FRAC_PI_2, 1.0);
    let mut be = h.take(Tool::round_sable, 0.04, thin(dark), 1.0 * 0.45);
    h.mark(c, &mut be, Mark { pts: &[(-0.068, 0.905), (0.0, 0.922), (0.064, 0.915)], pressure: (0.85, 0.9), ramps: (0.05, 0.2) }, None);
    if let Some(l) = rim {
        c.dry();
        let mut lb = h.take(Tool::round_sable, 0.014, lean(paint::color::mix(dark, l, 0.5, paint::Mix::Pigment)), 0.35 * 0.4);
        h.mark(c, &mut lb, Mark { pts: &[(-0.1, 0.785), (-0.05, 0.842), (0.03, 0.845)], pressure: (0.4, 0.25), ramps: (0.2, 0.5) }, None);
    }
    h.p(-0.08, 0.8)
}

/// The slimmer young man in a frock coat, white collar and student cap, his
/// right hand resting on `hand_on` (canvas units) if given.
#[allow(clippy::too_many_arguments)]
pub fn youth_in_frock(c: &mut Canvas, at: (f32, f32), size: f32, coat: Rgb, dark: Rgb, hair: Rgb, collar: Rgb, hand_on: Option<(f32, f32)>, rim: Option<Rgb>, seed: u64) {
    let mut h = Hand::new(at, size, seed);
    legs(c, &mut h, paint::color::mix(dark, coat, 0.3, paint::Mix::Pigment), dark, 0.025, 0.04);
    // frock coat: narrow torso to the waist, then tails flaring to the knee
    let p = body(coat);
    let mut cb = h.take(Tool::round_sable, 0.055, p, 1.0);
    for (i, u) in [-0.04f32, 0.04, 0.0].iter().enumerate() {
        if i % 2 == 0 {
            cb.reload(p, 1.0);
        }
        h.mark(c, &mut cb, Mark { pts: &[(*u, 0.82), (u * 0.85, 0.68), (u * 0.8, 0.56)], pressure: (0.8, 0.75), ramps: (0.05, 0.1) }, None);
    }
    cb.reload(p, 1.0);
    for u in [-0.035f32, 0.035, 0.0] {
        h.mark(c, &mut cb, Mark { pts: &[(u * 0.9, 0.58), (u * 1.2, 0.45), (u * 1.6, 0.33)], pressure: (0.7, 0.9), ramps: (0.05, 0.15) }, None);
    }
    h.line(c, &mut cb, &[(-0.085, 0.765), (-0.04, 0.825), (0.04, 0.825), (0.085, 0.765)], 0.7, 0.7);
    // left arm hangs at his side
    h.line(c, &mut cb, &[(-0.07, 0.78), (-0.085, 0.64), (-0.08, 0.5)], 0.6, 0.5);
    // right arm to the companion's shoulder
    if let Some(t) = hand_on {
        let tu = (t.0 - at.0) / size;
        let tv = (at.1 - t.1) / size;
        let e = (0.5 * (0.07 + tu) + 0.02, 0.5 * (0.78 + tv) - 0.06);
        h.mark(c, &mut cb, Mark { pts: &[(0.065, 0.78), e, (tu, tv)], pressure: (0.65, 0.5), ramps: (0.05, 0.2) }, None);
    } else {
        h.line(c, &mut cb, &[(0.07, 0.78), (0.085, 0.64), (0.08, 0.5)], 0.6, 0.5);
    }
    c.dry();
    // white collar standing up at the neck
    let mut wc = h.take(Tool::round_sable, 0.022, thin(collar), 0.8 * 0.45);
    h.mark(c, &mut wc, Mark { pts: &[(-0.03, 0.832), (0.0, 0.842), (0.03, 0.832)], pressure: (0.7, 0.7), ramps: (0.1, 0.3) }, None);
    // head, then the cap: a small flat dab resting on it
    let mut hd = h.take(Tool::round_sable, 0.055, thin(hair), 1.0 * 0.45);
    h.dab(c, &mut hd, 0.0, 0.882, 0.045, FRAC_PI_2, 1.0);
    let mut cp = h.take(Tool::round_sable, 0.036, thin(dark), 1.0 * 0.45);
    h.mark(c, &mut cp, Mark { pts: &[(-0.042, 0.905), (0.0, 0.918), (0.045, 0.91)], pressure: (0.85, 0.85), ramps: (0.05, 0.2) }, None);
    if let Some(l) = rim {
        c.dry();
        let mut lb = h.take(Tool::round_sable, 0.012, lean(paint::color::mix(dark, l, 0.5, paint::Mix::Pigment)), 0.35 * 0.4);
        h.mark(c, &mut lb, Mark { pts: &[(-0.08, 0.775), (-0.04, 0.832)], pressure: (0.4, 0.25), ramps: (0.2, 0.5) }, None);
    }
}
//! Evergreens written as brush gestures: the spruce as Friedrich places it,
//! a dark spire of drooping tiers (the evergreen against the dead oak).

use paint::{Canvas, Hand, Mark, Paint, Rgb, Tool};

/// A spruce: a trunk line, then tiers of drooping branch strokes from the top
/// down, each tier a little longer, the tip a single flick. `base` is where
/// the trunk meets the ground; `height` in canvas units.
pub fn spruce(c: &mut Canvas, base: (f32, f32), height: f32, color: Rgb, seed: u64) {
    let mut h = Hand::new(base, height, seed);
    h.tremor = 0.002;
    let p = Paint { color, hiding: 0.92, stiff: 0.6 };
    let mut t = h.take(Tool::round_sable, 0.014, p, 0.6);
    h.mark(c, &mut t, Mark { pts: &[(0.0, 0.0), (0.002, 0.5), (0.0, 1.0)], pressure: (0.9, 0.3), ramps: (0.0, 0.3) }, None);
    let mut b = h.take(Tool::round_sable, 0.028, p, 0.6);
    let tiers = 22 + (height / 12.0).min(16.0) as usize;
    let slim = h.rng.range(0.17, 0.24);
    for i in 0..tiers {
        let v = 0.96 - (i as f32 + h.rng.range(0.0, 0.6)) / tiers as f32 * 0.9;
        let reach = (0.015 + slim * (1.0 - v)) * h.rng.range(0.75, 1.1);
        if i % 3 == 0 {
            b.reload(p, 0.6);
        }
        for s in [-1.0f32, 1.0] {
            // out and down from the trunk, the tip turning a little up
            let droop = reach * h.rng.range(0.25, 0.45);
            let pts = [(s * 0.004, v), (s * reach * 0.55, v - droop), (s * reach, v - droop * 0.8)];
            h.mark(c, &mut b, Mark { pts: &pts, pressure: (0.9, 0.35), ramps: (0.0, 0.5) }, None);
        }
    }
    // the leader at the top
    h.mark(c, &mut t, Mark { pts: &[(0.0, 0.92), (0.001, 1.02)], pressure: (0.7, 0.2), ramps: (0.0, 0.5) }, None);
}
//! Brush physics study sheet: each row tests one behavior.

use paint::{Gesture, Held, Orient, Paint, Tool, hex};

fn main() {
    let o = paintings::run::Run::new("study_brushes");
    // lead-white priming on linen
    let mut c = paint::Canvas::new(o.width, 1.5, hex("#ece6d8")).with_linen(paint::Linen::fine(3));

    let ultramarine = hex("#1f2a78");
    let sienna = hex("#8a3b12");
    let sap = hex("#4f6b1c");
    let ivory_black = hex("#1a1816");
    let cad_yellow = hex("#f2c200");
    let cobalt = hex("#1c4fa0");
    let crimson = hex("#9a1030");
    let white = hex("#f4f1e8");
    let ochre = hex("#c08a2a");

    let wave = |x0: f32, y: f32, len: f32, amp: f32| -> Vec<(f32, f32)> {
        (0..6).map(|i| {
            let t = i as f32 / 5.0;
            (x0 + t * len, y + (t * std::f32::consts::TAU).sin() * amp)
        }).collect()
    };

    // ---- row 1: each tool, fully loaded, one S-stroke
    let tools = [
        (Tool::round_sable(8.0), ultramarine),
        (Tool::hog_flat(20.0), sienna),
        (Tool::filbert(16.0), sap),
        (Tool::fan(26.0), ivory_black),
        (Tool::rigger(1.6), ivory_black),
    ];
    for (i, (t, col)) in tools.iter().enumerate() {
        let mut b = Held::new(t.clone(), 10 + i as u64);
        b.load(Paint::body(*col), 1.0);
        let x = 30.0 + i as f32 * 190.0;
        c.drag(&mut b, &Gesture::new(wave(x, 60.0, 160.0, 14.0)), None);
    }

    // ---- row 2: pressure falls off → dry brush over the weave
    let mut b = Held::new(Tool::hog_flat(22.0), 20);
    b.load(Paint::body(sienna), 0.8);
    c.drag(&mut b, &Gesture::line((30.0, 150.0), (470.0, 150.0)).pressure(1.0, 0.12).ramps(0.03, 0.02), None);
    let mut b = Held::new(Tool::round_sable(10.0), 21);
    b.load(Paint::body(ultramarine), 0.5);
    c.drag(&mut b, &Gesture::new(wave(520.0, 150.0, 450.0, 8.0)).pressure(0.9, 0.3), None);

    // ---- row 3: wet into wet — yellow dragged through wet blue picks it up
    let mut b = Held::new(Tool::hog_flat(24.0), 30);
    for k in 0..4 {
        b.reload(Paint::body(cobalt), 1.0);
        let y = 215.0 + k as f32 * 16.0;
        c.drag(&mut b, &Gesture::line((30.0, y), (330.0, y)).pressure(0.9, 0.8), None);
    }
    let mut b = Held::new(Tool::filbert(14.0), 31);
    for k in 0..5 {
        b.reload(Paint::body(cad_yellow), 1.0);
        let x = 60.0 + k as f32 * 55.0;
        c.drag(&mut b, &Gesture::line((x, 200.0), (x + 20.0, 290.0)).pressure(0.95, 0.9), None);
    }
    // white into wet dark
    let mut b = Held::new(Tool::hog_flat(24.0), 32);
    for k in 0..4 {
        b.reload(Paint::body(ivory_black), 1.0);
        let y = 215.0 + k as f32 * 16.0;
        c.drag(&mut b, &Gesture::line((370.0, y), (620.0, y)), None);
    }
    let mut b = Held::new(Tool::round_sable(9.0), 33);
    b.load(Paint::body(white), 1.0);
    c.drag(&mut b, &Gesture::new(vec![(390.0, 280.0), (450.0, 215.0), (520.0, 280.0), (600.0, 210.0)]).pressure(0.9, 0.7), None);

    // blender: two wet colors side by side, badger zigzag across the join
    let mut b = Held::new(Tool::hog_flat(24.0), 34);
    for k in 0..5 {
        b.reload(Paint::body(ochre), 1.0);
        let y = 205.0 + k as f32 * 16.0;
        c.drag(&mut b, &Gesture::line((660.0, y), (810.0, y)), None);
        b.reload(Paint::body(crimson), 1.0);
        c.drag(&mut b, &Gesture::line((810.0, y), (970.0, y)), None);
    }
    let mut bl = Held::new(Tool::badger(34.0), 35);
    let zig: Vec<(f32, f32)> = (0..10).map(|i| (790.0 + if i % 2 == 0 { -18.0 } else { 18.0 }, 200.0 + i as f32 * 10.0)).collect();
    c.drag(&mut bl, &Gesture::new(zig).pressure(0.5, 0.5), None);
    let zig2: Vec<(f32, f32)> = (0..10).map(|i| (840.0 + if i % 2 == 0 { -14.0 } else { 14.0 }, 200.0 + i as f32 * 10.0)).collect();
    c.drag(&mut bl, &Gesture::new(zig2).pressure(0.35, 0.35), None);

    // ---- row 4: let it dry, then glaze crimson over part of rows 3
    c.dry();
    let mut g = Held::new(Tool::filbert(30.0), 40);
    for k in 0..3 {
        g.reload(Paint::glaze(crimson), 1.0 * 0.3);
        let y = 215.0 + k as f32 * 22.0;
        c.drag(&mut g, &Gesture::line((180.0, y), (520.0, y)).pressure(0.6, 0.6), None);
    }

    // ---- row 5: Cézanne-style hatching with a flat at a fixed angle, and fan dabs
    let mut b = Held::new(Tool::hog_flat(12.0), 50);
    let greens = [hex("#5a7a3a"), hex("#7d9a4a"), hex("#3f5f3a"), hex("#9aa860"), hex("#6f8fa0")];
    let mut r = paint::Rng::new(5);
    for k in 0..60 {
        b.reload(Paint::body(greens[k % greens.len()]), 0.7);
        let x = 40.0 + r.range(0.0, 380.0);
        let y = 340.0 + r.range(0.0, 90.0);
        let a = -0.9f32;
        c.drag(&mut b, &Gesture::line((x, y), (x + a.cos() * 18.0, y + a.sin() * 18.0)).orient(Orient::Fixed(a + std::f32::consts::FRAC_PI_2)).pressure(0.85, 0.7), None);
    }
    let mut fan = Held::new(Tool::fan(30.0), 51);
    for k in 0..14 {
        fan.reload(Paint::scumble(if k % 2 == 0 { hex("#3d5a2a") } else { hex("#8aa050") }), 0.5 * 0.6);
        let x = 480.0 + k as f32 * 34.0;
        let y = 400.0 + r.range(-20.0, 20.0);
        c.drag(&mut fan, &Gesture::line((x, y + 10.0), (x + 6.0, y - 30.0)).orient(Orient::Across).pressure(0.6, 0.3), None);
    }

    // ---- row 6: one dirty brush dragged across wet colors without cleaning
    let bands = [cobalt, cad_yellow, crimson, white, sap];
    let mut b = Held::new(Tool::hog_flat(26.0), 60);
    for (k, col) in bands.iter().enumerate() {
        b.reload(Paint::body(*col), 1.0);
        let x = 40.0 + k as f32 * 70.0;
        c.drag(&mut b, &Gesture::line((x, 480.0), (x, 610.0)).orient(Orient::Across), None);
    }
    let mut b = Held::new(Tool::filbert(18.0), 61);
    b.load(Paint::body(white), 0.6);
    for k in 0..3 {
        let y = 505.0 + k as f32 * 40.0;
        c.drag(&mut b, &Gesture::line((25.0, y), (400.0, y + 8.0)).pressure(0.9, 0.9), None);
    }
    // rigger twigs
    let mut rg = Held::new(Tool::rigger(1.4), 62);
    for k in 0..8 {
        rg.reload(Paint::body(ivory_black), 1.0);
        let x = 500.0 + k as f32 * 55.0;
        let pts: Vec<(f32, f32)> = (0..6).map(|i| (x + (i as f32 * 1.7).sin() * 8.0 + i as f32 * 6.0, 620.0 - i as f32 * 22.0)).collect();
        c.drag(&mut rg, &Gesture::new(pts).pressure(0.9, 0.2).ramps(0.02, 0.6), None);
    }

    c.relief(0.7, 0.04);
    o.save(&mut c);
}
//! Calibration sheet for the physical surface: a Friedrich canvas as bought
//! (linen + ground), then thin fluid paint (should pool in the ground's
//! hollows), a lean sky scumble and stiff body paint (should keep its marks).
//! Top band: bare ground. Then thin smalt-blue paint, a stiff white stroke
//! band, and a dark glaze.

use paint::{Gesture, Held, Mask, Orient, Paint, Pigment, Style, Tool, hex};

fn main() {
    let o = paintings::run::Run::new("study_ground");
    let st = Style::friedrich();
    let mut c = st.prepare(o.width, 2.0, o.seed);
    if o.stage(&mut c, "ground") {
        return;
    }
    let h = c.height();
    // band 2: thin fluid blue, laid with a soft filbert in long strokes
    let fr = c.frame();
    let band = |a: f32, b: f32| Mask::from_fn(fr, move |_, y| if y >= a * h && y < b * h { 1.0 } else { 0.0 });
    let b2 = band(0.25, 0.5);
    let mut fil = Held::new(Tool::filbert(30.0), 3);
    for i in 0..12 {
        fil.reload(Paint { color: hex("#5d6f94"), hiding: 0.35, stiff: 0.15 }, 0.8 * 0.15);
        let y = h * 0.26 + i as f32 * h * 0.02;
        c.drag(&mut fil, &Gesture::new(vec![(0.0, y), (1000.0, y)]).pressure(0.8, 0.8).orient(Orient::Across), Some(&b2));
    }
    c.dry();
    // band 3: stiff lead white, hog brush, keeps its marks
    let b3 = band(0.5, 0.75);
    let mut hog = Held::new(Tool::hog_flat(24.0), 4);
    for i in 0..10 {
        hog.reload(Paint { color: hex("#e6e1d3"), hiding: 0.9, stiff: 1.0 }, 1.0 * 1.0);
        let y = h * 0.51 + i as f32 * h * 0.024;
        c.drag(&mut hog, &Gesture::new(vec![(0.0, y), (500.0, y + 2.0), (1000.0, y)]).pressure(0.85, 0.85).orient(Orient::Across), Some(&b3));
    }
    c.dry();
    // band 4: a dark umber glaze
    let b4 = band(0.75, 1.0);
    c.glaze(&Pigment::transparent(hex("#3b2a1c")), Some(&b4), |_, _| 2.0);
    c.relief(0.35, 0.02);
    o.save(&mut c);
}
