//! Fractal noise in canvas units.

use noise::{MultiFractal, NoiseFn, Perlin};

pub struct Fbm {
    f: noise::Fbm<Perlin>,
    inv_period: f64,
}

impl Fbm {
    /// `period` is the size (in units) of the largest feature.
    pub fn new(seed: u32, octaves: usize, period: f32) -> Self {
        let f = noise::Fbm::<Perlin>::new(seed)
            .set_octaves(octaves)
            .set_persistence(0.5)
            .set_lacunarity(2.0);
        Fbm { f, inv_period: 1.0 / period as f64 }
    }

    pub fn with_persistence(mut self, p: f64) -> Self {
        self.f = self.f.set_persistence(p);
        self
    }

    /// Roughly in [-1, 1].
    #[inline]
    pub fn get(&self, x: f32, y: f32) -> f32 {
        self.f.get([x as f64 * self.inv_period, y as f64 * self.inv_period]) as f32
    }

    /// Remapped to [0, 1].
    #[inline]
    pub fn get01(&self, x: f32, y: f32) -> f32 {
        (self.get(x, y) * 0.5 + 0.5).clamp(0.0, 1.0)
    }
}
//! Small deterministic RNG and hashing (no external deps).

#[derive(Clone, Debug)]
pub struct Rng(u64);

impl Rng {
    pub fn new(seed: u64) -> Self {
        Rng(seed ^ 0x9E37_79B9_7F4A_7C15)
    }

    pub fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// Uniform in [0, 1).
    pub fn f(&mut self) -> f32 {
        (self.next_u64() >> 40) as f32 / (1u64 << 24) as f32
    }

    /// Uniform in [lo, hi).
    pub fn range(&mut self, lo: f32, hi: f32) -> f32 {
        lo + (hi - lo) * self.f()
    }

    /// Roughly normal (sum of uniforms), mean 0, sd ~1.
    pub fn normal(&mut self) -> f32 {
        (self.f() + self.f() + self.f() + self.f() - 2.0) * 1.732
    }

    pub fn chance(&mut self, p: f32) -> bool {
        self.f() < p
    }
}

/// Hash two ints + seed to [0, 1).
#[inline]
pub fn hash2(x: i64, y: i64, seed: u64) -> f32 {
    let mut h = (x as u64).wrapping_mul(0x8DA6_B343)
        ^ (y as u64).wrapping_mul(0xD816_3841)
        ^ seed.wrapping_mul(0xCB1A_B31F);
    h ^= h >> 33;
    h = h.wrapping_mul(0xFF51_AFD7_ED55_8CCD);
    h ^= h >> 33;
    h = h.wrapping_mul(0xC4CE_B9FE_1A85_EC53);
    h ^= h >> 33;
    (h >> 40) as f32 / (1u64 << 24) as f32
}
