                    let pts: Vec<(f32, f32)> = (0..n)
                        .map(|i| {
                            let w = l.w[i];
                            (l.pts[i].0 + normals[i].0 * w * u, l.pts[i].1 + normals[i].1 * w * u)
                        })
                        .collect();
