//! "Evening on the Baltic Shore, with Anchor" — an original painting in the
//! manner of Caspar David Friedrich (Dresden practice, c. 1820–25).
//!
//! The afterglow of a sunset that has already gone below the sea, left of
//! center; a thin waxing crescent moon high on the right with the evening
//! star low in the glow. A brig stands out to sea on the axis of the moon.
//! On the shore a woman in a dark dress, seen from behind, watches it go; in
//! the dark foreground an old anchor lies half sunk among granite erratics.
//! (Anchor = hope; ship = the passage of life; moon = the promise beyond it;
//! the figure turned away so we look with her — Friedrich's Rückenfigur.)
//!
//! Order of work follows notes/research/friedrich_materials.md: bought
//! ground, graphite underdrawing, very thin dead coloring, sky, distance to
//! foreground, figure last, then a darkening glaze toward the edges (his
//! advice to Carus) and varnish.

use paint::color::{Mix, gradient, mix};
use paint::{Canvas, Frame, Gesture, Held, Mask, Orient, Paint, Rgb, Rng, Shape, Style, Tool, hex, smoothstep};
use paintings::run::{Finish, Run};

const ASPECT: f32 = 1.4;
/// Sea horizon (units from the top).
const HOR: f32 = 440.0;
/// Where the sunset glow sits (x).
const GX: f32 = 360.0;
/// The moon.
const MOON: (f32, f32) = (655.0, 128.0);
/// The brig (waterline center).
const SHIP: (f32, f32) = (668.0, 474.0);

fn hgt() -> f32 {
    1000.0 / ASPECT
}

/// The waterline: where the last thin wave runs out on the sand.
fn shore_y(x: f32) -> f32 {
    578.0 + 10.0 * (x * 0.004 + 0.7).sin() + 5.0 * (x * 0.013).sin() - 0.012 * (x - 500.0)
}

/// Afterglow sky: deep dusky blue overhead, through a cool violet-grey, to a
/// rose and then a pale yellow band on the horizon; warmest above the place
/// the sun went down.
fn sky(x: f32, y: f32) -> Rgb {
    let t = (y / HOR).clamp(0.0, 1.0);
    let base = gradient(
        &[
            (0.0, hex("#3e4a66")),
            (0.28, hex("#65718f")),
            (0.55, hex("#9b98ab")),
            (0.74, hex("#c7aeaa")),
            (0.9, hex("#e2c39c")),
            (1.0, hex("#ecd6a4")),
        ],
        t,
        Mix::Light,
    );
    let d = (x - GX) / 420.0;
    let glow = (-d * d).exp() * smoothstep(0.45, 1.0, t);
    let warm = mix(base, hex("#f1d29a"), glow * 0.55, Mix::Light);
    // far from the glow, the low sky is greyer and cooler
    let cool = (1.0 - (-d * d * 0.6).exp()) * smoothstep(0.5, 1.0, t);
    mix(warm, hex("#a9a3ab"), cool * 0.35, Mix::Light)
}

/// The sea: near the horizon it mirrors the low sky, darker; toward the shore
/// a deep cool slate. A lighter column lies under the glow.
fn sea(x: f32, y: f32) -> Rgb {
    let t = ((y - HOR) / (shore_y(x) - HOR)).clamp(0.0, 1.0);
    let base = gradient(
        &[(0.0, hex("#b3a597")), (0.12, hex("#8c8a8e")), (0.4, hex("#5f6874")), (1.0, hex("#38414b"))],
        t,
        Mix::Light,
    );
    let d = (x - GX) / (70.0 + 140.0 * t);
    let col = (-d * d).exp() * (1.0 - t).powf(0.7);
    mix(base, hex("#d8c49c"), col * 0.45, Mix::Light)
}

/// The shore: wet sand at the waterline taking a little sky, then darker
/// sand and shingle, darkest at the bottom edge.
fn shore(x: f32, y: f32) -> Rgb {
    let t = ((y - shore_y(x)) / (hgt() - shore_y(x))).clamp(0.0, 1.0);
    gradient(
        &[(0.0, hex("#7a746c")), (0.08, hex("#5d554a")), (0.4, hex("#43392e")), (1.0, hex("#231d17"))],
        t,
        Mix::Light,
    )
}

/// A granite erratic: outline points (clockwise), and where light comes from.
struct Rock {
    pts: Vec<(f32, f32)>,
}

fn rocks() -> Vec<Rock> {
    let h = hgt();
    vec![
        // the big boulder at the right foreground, cut by the frame
        Rock { pts: vec![(812.0, h + 5.0), (800.0, 668.0), (818.0, 628.0), (858.0, 604.0), (915.0, 592.0), (968.0, 600.0), (1005.0, 612.0), (1005.0, h + 5.0)] },
        // a lower one in front of it
        Rock { pts: vec![(735.0, h + 5.0), (742.0, 690.0), (770.0, 672.0), (812.0, 676.0), (838.0, 700.0), (842.0, h + 5.0)] },
        // left group
        Rock { pts: vec![(-5.0, h + 5.0), (-5.0, 628.0), (30.0, 614.0), (78.0, 618.0), (112.0, 640.0), (126.0, 676.0), (120.0, h + 5.0)] },
        Rock { pts: vec![(96.0, h + 5.0), (104.0, 684.0), (132.0, 666.0), (170.0, 668.0), (196.0, 690.0), (200.0, h + 5.0)] },
        // small stones out near the waterline
        Rock { pts: vec![(418.0, 612.0), (424.0, 600.0), (440.0, 596.0), (455.0, 602.0), (458.0, 613.0)] },
        Rock { pts: vec![(596.0, 606.0), (600.0, 597.0), (612.0, 594.0), (622.0, 600.0), (623.0, 607.0)] },
        Rock { pts: vec![(262.0, 618.0), (268.0, 607.0), (282.0, 604.0), (293.0, 610.0), (294.0, 619.0)] },
    ]
}

fn rock_mask(fr: Frame, r: &Rock) -> Mask {
    Mask::from_shape(fr, Shape::new().smooth_poly(&r.pts))
}

/// Drag a brush through canvas points.
fn stroke(c: &mut Canvas, b: &mut Held, pts: &[(f32, f32)], p0: f32, p1: f32, clip: Option<&Mask>) {
    let g = Gesture::new(pts.to_vec()).pressure(p0, p1).ramps(0.1, 0.25).orient(Orient::Across);
    c.drag(b, &g, clip);
}

fn main() {
    let run = Run::new("fresh_coast");
    let st = Style::friedrich();
    let pal = &st.palette;
    let h = hgt();
    let mut c = st.prepare(run.width, ASPECT, run.seed);
    let fr = c.frame();
    let mut rng = Rng::new(run.seed * 977 + 5);
    if run.stage(&mut c, "ground") {
        return;
    }

    // ---- underdrawing: graphite, a faint first outline, then firmer; the
    // horizon ruled against a straightedge
    {
        let graphite = Paint { color: hex("#3b3834"), hiding: 0.35, stiff: 0.3 };
        let mut pen = Held::new(st.line_tool(0.55), 11);
        pen.load(graphite, 0.5);
        let g = Gesture::line((0.0, HOR), (1000.0, HOR + 0.6)).pressure(0.35, 0.35).shake(0.15);
        c.drag(&mut pen, &g, None);
        // waterline
        let wl: Vec<(f32, f32)> = (0..=20).map(|i| (i as f32 * 50.0, shore_y(i as f32 * 50.0))).collect();
        pen.load(graphite, 0.4);
        stroke(&mut c, &mut pen, &wl, 0.3, 0.3, None);
        for r in rocks() {
            pen.load(graphite, 0.4);
            let mut p = r.pts.clone();
            p.push(p[0]);
            stroke(&mut c, &mut pen, &p, 0.35, 0.3, None);
        }
        // the brig, the figure, the anchor: placed with a few lines
        pen.load(graphite, 0.4);
        stroke(&mut c, &mut pen, &[(SHIP.0 - 22.0, SHIP.1), (SHIP.0 + 20.0, SHIP.1 - 1.0)], 0.35, 0.3, None);
        stroke(&mut c, &mut pen, &[(SHIP.0 - 6.0, SHIP.1), (SHIP.0 - 6.0, SHIP.1 - 64.0)], 0.3, 0.3, None);
        stroke(&mut c, &mut pen, &[(SHIP.0 + 8.0, SHIP.1), (SHIP.0 + 8.0, SHIP.1 - 58.0)], 0.3, 0.3, None);
        stroke(&mut c, &mut pen, &[(548.0, 604.0), (548.0, 540.0)], 0.3, 0.3, None);
        stroke(&mut c, &mut pen, &[(300.0, 690.0), (360.0, 632.0)], 0.35, 0.3, None);
        c.dry();
    }
    if run.stage(&mut c, "drawing") {
        return;
    }

    // ---- dead coloring: a very thin warm-brown underpainting of the land
    // and a thin cool one of the sea; the sky is left to the ground
    {
        let land = Mask::from_fn(fr, |x, y| smoothstep(shore_y(x) - 4.0, shore_y(x) + 4.0, y));
        let hd = st.broad().color(|_, y| mix(hex("#5a4636"), hex("#2e241c"), (y - 580.0) / 140.0, Mix::Light)).medium(0.7).coverage(1.6);
        c.work(&land, &hd, 21);
        let water = Mask::from_fn(fr, |x, y| smoothstep(HOR - 2.0, HOR + 3.0, y) * (1.0 - smoothstep(shore_y(x) - 2.0, shore_y(x) + 4.0, y)));
        let hd = st.broad().color(|x, y| mix(sea(x, y), hex("#4a4a50"), 0.4, Mix::Light)).medium(0.75).coverage(1.4).angle(|_, _| 0.0);
        c.work(&water, &hd, 22);
        c.dry();
    }
    if run.stage(&mut c, "dead") {
        return;
    }

    // ---- sky: long horizontal strokes of thin paint, laid top to bottom
    // in the order a painter works a gradient, then fused with the badger,
    // then stippled over to break it into the fine dotted texture
    {
        let sky_m = Mask::from_fn(fr, |_, y| 1.0 - smoothstep(HOR + 1.0, HOR + 6.0, y));
        let hd = st.broad().color(sky).angle(|_, _| 0.0).angle_jitter(0.015).length(140.0, 320.0).coverage(3.0);
        c.work(&sky_m, &hd, 31);
        if let Some(b) = st.blend() {
            c.work(&sky_m, &b.angle(|_, _| 0.0), 32);
        }
        c.dry();
        // stipple: a small round, dabbing, in thin paint near the sky tone
        let stip = paint::Handling::new(Tool::round_sable(5.0))
            .mixed(pal, 0.55)
            .color(sky)
            .length(1.5, 3.0)
            .coverage(1.4)
            .pressure(0.35, 0.6)
            .dips(6, 0.25, 0.4)
            .ramps(0.3, 0.5)
            .angle_jitter(1.5);
        c.work(&sky_m, &stip, 33);
        c.dry();
    }
    if run.stage(&mut c, "sky") {
        return;
    }

    // ---- clouds: long thin bands of stratus, violet-grey with warm lit
    // undersides near the glow; each a few long strokes of a soft filbert
    {
        let bands: [(f32, f32, f32, f32); 5] = [
            // (y, x0, x1, thickness)
            (352.0, -20.0, 560.0, 7.0),
            (366.0, 120.0, 820.0, 5.0),
            (318.0, 420.0, 1020.0, 4.0),
            (236.0, 80.0, 470.0, 3.5),
            (392.0, 560.0, 1020.0, 4.0),
        ];
        for (k, &(y, x0, x1, th)) in bands.iter().enumerate() {
            let tone = mix(sky(0.5 * (x0 + x1), y), hex("#6c6478"), 0.55, Mix::Light);
            let lit = mix(sky(GX, y + 25.0), hex("#e4b48a"), 0.4, Mix::Light);
            let mut b = Held::new(Tool { ragged: 0.6, ..Tool::filbert(th * 2.2) }, 40 + k as u64);
            let n = ((x1 - x0) / 90.0).ceil() as usize;
            for i in 0..n {
                let xa = x0 + (x1 - x0) * i as f32 / n as f32 + rng.range(-20.0, 10.0);
                let xb = xa + (x1 - x0) / n as f32 + rng.range(10.0, 50.0);
                let yy = y + rng.normal() * 1.5;
                let taper = 1.0 - ((i as f32 + 0.5) / n as f32 - 0.5).abs() * 1.2;
                b.reload(pal.paint(tone, 0.5), 0.45);
                let pts = vec![(xa, yy + rng.normal()), (0.5 * (xa + xb), yy + rng.normal() * 1.5), (xb, yy + rng.normal())];
                c.drag(&mut b, &Gesture::new(pts).pressure(0.55 * taper + 0.15, 0.45 * taper + 0.1).ramps(0.3, 0.4), None);
                // lit underside
                let glow = (-((0.5 * (xa + xb) - GX) / 300.0).powi(2)).exp();
                if glow > 0.2 {
                    b.reload(pal.paint(lit, 0.55), 0.3 * glow);
                    let pts = vec![(xa + 10.0, yy + th * 0.5), (xb - 10.0, yy + th * 0.55)];
                    c.drag(&mut b, &Gesture::new(pts).pressure(0.35, 0.25).ramps(0.3, 0.4), None);
                }
            }
        }
        // fuse the cloud edges into the sky, gently
        if let Some(bl) = st.blend() {
            let m = Mask::from_fn(fr, |_, y| smoothstep(220.0, 240.0, y) * (1.0 - smoothstep(400.0, 420.0, y)));
            c.work(&m, &bl.pressure(0.3, 0.4).coverage(1.5).angle(|_, _| 0.0), 45);
        }
        c.dry();
    }

    // ---- the crescent moon and the evening star
    {
        let (mx, my) = MOON;
        let r = 12.0;
        // earthshine: the dark of the disc a breath lighter than the sky
        let mut e = Held::new(Tool::round_sable(r * 1.6), 50);
        e.load(pal.paint(mix(sky(mx, my), hex("#b8b8c0"), 0.25, Mix::Light), 0.7), 0.2);
        c.drag(&mut e, &Gesture::new(vec![(mx - 1.0, my), (mx + 1.0, my)]).pressure(0.6, 0.6).ramps(0.0, 0.0).shake(0.0), None);
        c.dry();
        // the sickle: lit side toward the lower left, where the sun went
        let mut b = Held::new(Tool::round_sable(4.2), 51);
        let white = pal.paint(hex("#f4ecd0"), 0.1);
        for pass in 0..2 {
            b.reload(white, 0.8);
            let pts: Vec<(f32, f32)> = (0..=10)
                .map(|i| {
                    let a = 0.35 * std::f32::consts::PI + i as f32 / 10.0 * std::f32::consts::PI * 1.05;
                    let rr = r - 1.8 - pass as f32 * 0.8;
                    (mx + a.cos() * rr * -1.0, my + a.sin() * rr * 0.98)
                })
                .collect();
            let g = Gesture::new(pts).pressure(0.25, 0.25).ramps(0.45, 0.45).shake(0.2);
            c.drag(&mut b, &g, None);
        }
        // evening star
        let mut s = Held::new(Tool::round_sable(2.4), 52);
        s.load(pal.paint(hex("#fbf3dc"), 0.1), 0.8);
        c.drag(&mut s, &Gesture::new(vec![(292.0, 296.0), (292.3, 296.4)]).pressure(0.8, 0.8).ramps(0.0, 0.3).shake(0.0), None);
        c.dry();
    }
    if run.stage(&mut c, "clouds") {
        return;
    }

    // ---- the far coast: a low blue strip on the left horizon
    {
        let coast = |x: f32| HOR - 9.0 * smoothstep(250.0, 30.0, x) - 3.0 * (x * 0.03).sin().abs() * smoothstep(250.0, 60.0, x);
        let m = Mask::from_fn(fr, move |x, y| {
            let top = coast(x);
            if x > 260.0 { 0.0 } else { smoothstep(top - 0.8, top + 0.8, y) * (1.0 - smoothstep(HOR + 0.5, HOR + 2.0, y)) }
        });
        let hd = st.detail().color(|_, _| hex("#8a8698")).medium(0.4).angle(|_, _| 0.0).length(10.0, 30.0).clip(true);
        c.work(&m, &hd, 60);
        c.dry();
    }

    // ---- the sea: horizontal strokes, lightest at the horizon; then the
    // swells as long lighter lines, closer together in the distance
    {
        let water = Mask::from_fn(fr, |x, y| smoothstep(HOR - 0.5, HOR + 1.5, y) * (1.0 - smoothstep(shore_y(x), shore_y(x) + 4.0, y)));
        let hd = st.broad().color(sea).angle(|_, _| 0.0).angle_jitter(0.01).length(100.0, 260.0).coverage(3.0).medium(0.35);
        c.work(&water, &hd, 70);
        if let Some(b) = st.blend() {
            c.work(&water, &b.angle(|_, _| 0.0).pressure(0.35, 0.45), 71);
        }
        c.dry();
        // swells: thin light lines of reflected sky, dark troughs
        let mut rg = Held::new(Tool::round_sable(1.4), 72);
        let mut y = HOR + 3.0;
        let mut k = 0;
        while y < 572.0 {
            let t = (y - HOR) / 140.0;
            let x0 = rng.range(-50.0, 900.0);
            let len = rng.range(80.0, 300.0) * (0.6 + t);
            let yy = y;
            let lightc = mix(sea(x0 + len * 0.5, yy - 6.0), hex("#e6d3b0"), 0.35 * (1.0 - t).max(0.0), Mix::Light);
            let dark = mix(sea(x0 + len * 0.5, yy + 6.0), hex("#262b33"), 0.4, Mix::Light);
            let col = if k % 3 == 2 { dark } else { lightc };
            rg.reload(pal.paint(col, 0.35), 0.6);
            let w = Tool::round_sable(0.8 + 3.0 * t);
            rg.tool = w;
            let pts = vec![(x0, yy), (x0 + len * 0.5, yy + rng.normal() * 0.4), (x0 + len, yy + rng.normal() * 0.4)];
            let g = Gesture::new(pts).pressure(0.4, 0.3).ramps(0.3, 0.4);
            let clipm = &water;
            c.drag(&mut rg, &g, Some(clipm));
            y += 0.6 + 7.0 * t * t + rng.range(0.0, 1.2);
            k += 1;
        }
        c.dry();
    }
    if run.stage(&mut c, "sea") {
        return;
    }

    // ---- the shore: sand, wet at the waterline, then darker shingle
    {
        let land = Mask::from_fn(fr, |x, y| smoothstep(shore_y(x) - 1.5, shore_y(x) + 2.0, y));
        let hd = st.body().color(shore).angle(|_, _| 0.0).angle_jitter(0.05).length(30.0, 90.0).coverage(2.5).medium(0.3);
        c.work(&land, &hd, 80);
        c.dry();
        // the last thin wave: a light line along the water's edge
        let mut b = Held::new(Tool::round_sable(1.6), 81);
        let pts: Vec<(f32, f32)> = (0..=25).map(|i| (i as f32 * 40.0 - 10.0, shore_y(i as f32 * 40.0 - 10.0) + 1.0)).collect();
        for seg in pts.windows(4).step_by(3) {
            b.reload(pal.paint(hex("#c6bca8"), 0.3), 0.5);
            stroke(&mut c, &mut b, seg, 0.4, 0.3, None);
        }
        // shingle: small stones dabbed in, darker and lighter
        let mut s = Held::new(Tool::round_sable(3.0), 82);
        for _ in 0..500 {
            let x = rng.range(0.0, 1000.0);
            let y = rng.range(shore_y(x) + 8.0, h);
            let t = (y - shore_y(x)) / (h - shore_y(x));
            let sz = 1.0 + 4.0 * t;
            let col = if rng.chance(0.4) { mix(shore(x, y), hex("#8a7e6c"), 0.5, Mix::Light) } else { mix(shore(x, y), hex("#1b1612"), 0.5, Mix::Light) };
            s.tool = Tool::round_sable(sz);
            s.reload(pal.paint(col, 0.2), 0.5);
            let a = rng.range(-0.3, 0.3);
            c.drag(&mut s, &Gesture::new(vec![(x, y), (x + a.cos() * sz * 0.8, y + a.sin() * sz * 0.8)]).pressure(0.7, 0.6).ramps(0.1, 0.3), None);
        }
        c.dry();
    }

    // ---- the brig, standing out to sea, and a far sail on the horizon
    paint_ship(&mut c, st.palette.clone(), SHIP, 1.0, 90);
    paint_ship(&mut c, st.palette.clone(), (176.0, HOR + 1.5), 0.28, 91);
    if run.stage(&mut c, "ships") {
        return;
    }

    // ---- boulders: dark granite, lit on top by the glow behind
    for (k, r) in rocks().iter().enumerate() {
        let m = rock_mask(fr, r);
        let (mut x0, mut y0, mut x1, mut y1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
        for &(x, y) in &r.pts {
            x0 = x0.min(x);
            y0 = y0.min(y);
            x1 = x1.max(x);
            y1 = y1.max(y.min(h));
        }
        let cx = 0.5 * (x0 + x1);
        let rh = (y1 - y0).max(1.0);
        let col = move |x: f32, y: f32| {
            let v = ((y - y0) / rh).clamp(0.0, 1.0);
            let side = ((x - cx) / (x1 - x0)).clamp(-0.5, 0.5);
            let dark = gradient(&[(0.0, hex("#5e554c")), (0.35, hex("#3b342e")), (1.0, hex("#1d1915"))], v, Mix::Light);
            mix(dark, hex("#17130f"), (side + 0.5) * 0.35, Mix::Light)
        };
        let small = rh < 30.0;
        let tool_w = if small { 3.0 } else { 9.0 };
        let hd = paint::Handling::new(Tool { lay: 0.7, push: 0.06, ..Tool::filbert(tool_w) })
            .mixed(pal, 0.2)
            .color(col)
            .length(tool_w * 1.5, tool_w * 5.0)
            .coverage(3.0)
            .pressure(0.6, 0.9)
            .dips(2, 0.56, 0.6)
            .angle(move |x, _| 1.2 + (x - cx) / (x1 - x0))
            .clip(true)
            .threshold(0.15);
        c.work(&m, &hd, 100 + k as u64);
        c.dry();
        // light on the crown: lean paint dragged across the top with little pressure
        let mut b = Held::new(Tool { ragged: 0.6, ..Tool::round_sable(tool_w * 0.6) }, 110 + k as u64);
        let top: Vec<(f32, f32)> = r.pts.iter().filter(|p| p.1 < y0 + rh * 0.3).map(|&(x, y)| (x, y + 2.0)).collect();
        if top.len() >= 2 {
            let mut top = top;
            top.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
            b.load(pal.paint(hex("#8c7b68"), 0.4), 0.4);
            c.drag(&mut b, &Gesture::new(top).pressure(0.45, 0.3).ramps(0.2, 0.4), Some(&m));
        }
        c.dry();
    }
    if run.stage(&mut c, "rocks") {
        return;
    }

    // ---- the anchor, half sunk in the shingle
    paint_anchor(&mut c, pal, 92);

    // ---- the figure, last
    paint_woman(&mut c, pal, (548.0, 606.0), 62.0, 93);
    if run.stage(&mut c, "figure") {
        return;
    }

    // ---- a dark glaze toward the edges, keeping the glow and moon clear
    {
        let all = Mask::full(fr);
        let edge = |x: f32, y: f32| {
            let dx = (x - 500.0) / 560.0;
            let dy = (y - 330.0) / 420.0;
            smoothstep(0.55, 1.15, (dx * dx + dy * dy).sqrt())
        };
        let gl = st.glaze(0.9).color(|_, _| hex("#3a2c20")).angle(|_, _| 0.0).load_at(edge).threshold(0.0);
        c.work(&all, &gl, 120);
        c.dry();
    }

    run.finish(&mut c, &Finish::aged((0.25, 0.02)));
}

/// A brig seen from astern-quarter, standing out to sea: dark hull, two
/// masts with square sails in three tiers, a jib forward. `s` scales it.
fn paint_ship(c: &mut Canvas, pal: paint::Palette, at: (f32, f32), s: f32, seed: u64) {
    let (x, y) = at;
    let mut rng = Rng::new(seed);
    let hull = pal.paint(hex("#221d19"), 0.15);
    let sail_dark = pal.paint(hex("#5f5a57"), 0.2);
    let sail_lit = pal.paint(hex("#b8a78e"), 0.25);
    let line = pal.paint(hex("#2a2622"), 0.2);
    // hull: two strokes, the lower shorter (the stern rounds under)
    let mut b = Held::new(Tool::round_sable(4.5 * s), seed);
    b.load(hull, 0.8);
    c.drag(&mut b, &Gesture::new(vec![(x - 20.0 * s, y - 2.5 * s), (x, y - 2.0 * s), (x + 22.0 * s, y - 3.5 * s)]).pressure(0.9, 0.7).ramps(0.05, 0.2), None);
    c.drag(&mut b, &Gesture::new(vec![(x - 16.0 * s, y), (x + 16.0 * s, y - 0.5 * s)]).pressure(0.8, 0.6).ramps(0.05, 0.3), None);
    c.dry();
    // masts
    let mut m = Held::new(Tool::rigger(0.7 * s.max(0.5)), seed + 1);
    for &(mx, top) in &[(-5.0f32, 66.0f32), (9.0, 60.0)] {
        m.reload(line, 0.8);
        c.drag(&mut m, &Gesture::new(vec![(x + mx * s, y - 3.0 * s), (x + mx * s + 0.3, y - top * s)]).pressure(0.6, 0.35).ramps(0.0, 0.2).shake(0.2), None);
    }
    // square sails: courses, topsails, topgallants, each a few short strokes
    // across, narrowing upward; the shadowed face, then a lit edge
    let mut sb = Held::new(Tool::filbert(5.0 * s), seed + 2);
    for &(mx, top) in &[(-5.0f32, 66.0f32), (9.0, 60.0)] {
        let tiers = [(0.18, 0.42, 13.0), (0.45, 0.68, 10.5), (0.71, 0.88, 7.5)];
        for &(a, bb, half) in &tiers {
            let ya = y - top * s * a;
            let yb = y - top * s * bb;
            let rows = ((ya - yb) / (3.0 * s)).ceil().max(1.0) as usize;
            for rI in 0..rows {
                let yy = ya - (ya - yb) * (rI as f32 + 0.5) / rows as f32;
                let hw = half * s * (1.0 - 0.1 * rI as f32 / rows as f32);
                sb.reload(sail_dark, 0.5);
                let cx = x + mx * s + 1.5 * s;
                c.drag(&mut sb, &Gesture::new(vec![(cx - hw, yy), (cx + hw, yy + rng.normal() * 0.2)]).pressure(0.7, 0.7).ramps(0.1, 0.1).orient(Orient::Across), None);
            }
        }
    }
    c.dry();
    // lit edges (the glow is behind to the left): the left leech of each sail
    let mut lb = Held::new(Tool::round_sable(1.6 * s.max(0.5)), seed + 3);
    for &(mx, top) in &[(-5.0f32, 66.0f32), (9.0, 60.0)] {
        for &(a, bb, half) in &[(0.18f32, 0.42f32, 13.0f32), (0.45, 0.68, 10.5), (0.71, 0.88, 7.5)] {
            lb.reload(sail_lit, 0.5);
            let cx = x + mx * s + 1.5 * s;
            c.drag(&mut lb, &Gesture::new(vec![(cx - half * s + 0.8 * s, y - top * s * a), (cx - half * s * 0.95 + 0.8 * s, y - top * s * bb)]).pressure(0.5, 0.4).ramps(0.1, 0.3), None);
        }
    }
    // jib and staysail: triangles forward (right), drawn as strokes
    let fx = x + 9.0 * s;
    sb.reload(sail_dark, 0.5);
    c.drag(&mut sb, &Gesture::new(vec![(fx + 3.0 * s, y - 52.0 * s), (fx + 10.0 * s, y - 28.0 * s), (fx + 20.0 * s, y - 8.0 * s)]).pressure(0.3, 0.9).ramps(0.1, 0.1), None);
    // rigging: stays from mastheads to bow and stern
    let mut rgb = Held::new(Tool::rigger(0.35 * s.max(0.6)), seed + 4);
    rgb.load(line, 0.5);
    for (a, b2) in [((x + 9.0 * s, y - 60.0 * s), (x + 30.0 * s, y - 5.0 * s)), ((x - 5.0 * s, y - 66.0 * s), (x - 20.0 * s, y - 4.0 * s)), ((x - 5.0 * s, y - 66.0 * s), (x + 9.0 * s, y - 60.0 * s))] {
        c.drag(&mut rgb, &Gesture::line(a, b2).pressure(0.3, 0.3).ramps(0.0, 0.0).shake(0.1), None);
    }
    c.dry();
}

/// An old stocked anchor lying tilted, one arm buried in the shingle, its
/// ring up. Painted in dark rusty iron with a warm glint of the sky on top.
fn paint_anchor(c: &mut Canvas, pal: &paint::Palette, seed: u64) {
    let iron = pal.paint(hex("#2a211c"), 0.15);
    let rust = pal.paint(hex("#7a4c33"), 0.35);
    let wood = pal.paint(hex("#3d3027"), 0.2);
    // shank from the crown (buried end, lower left) up to the ring
    let crown = (298.0, 676.0);
    let top = (372.0, 616.0);
    let mut b = Held::new(Tool::round_sable(5.0), seed);
    b.load(iron, 0.9);
    c.drag(&mut b, &Gesture::new(vec![crown, ((crown.0 + top.0) * 0.5, (crown.1 + top.1) * 0.5 - 1.0), top]).pressure(0.95, 0.75).ramps(0.05, 0.1), None);
    // the arm that shows: curving up from the crown, ending in a fluke
    b.reload(iron, 0.9);
    c.drag(&mut b, &Gesture::new(vec![(crown.0 + 2.0, crown.1), (crown.0 + 22.0, crown.1 + 6.0), (crown.0 + 42.0, crown.1 - 2.0), (crown.0 + 50.0, crown.1 - 14.0)]).pressure(0.9, 0.7).ramps(0.05, 0.2), None);
    // fluke: a broad spade at the arm's end
    let mut f = Held::new(Tool::filbert(8.0), seed + 1);
    f.load(iron, 0.9);
    c.drag(&mut f, &Gesture::new(vec![(crown.0 + 43.0, crown.1 - 4.0), (crown.0 + 52.0, crown.1 - 19.0)]).pressure(0.9, 0.5).ramps(0.0, 0.4), None);
    // the other arm goes down into the shingle: only its root
    b.reload(iron, 0.7);
    c.drag(&mut b, &Gesture::new(vec![(crown.0, crown.1), (crown.0 - 12.0, crown.1 + 3.0)]).pressure(0.8, 0.4).ramps(0.0, 0.5), None);
    c.dry();
    // the wooden stock, across the shank below the ring
    let mut w = Held::new(Tool::round_sable(4.0), seed + 2);
    w.load(wood, 0.9);
    let sc = (top.0 - 9.0, top.1 + 8.0);
    c.drag(&mut w, &Gesture::new(vec![(sc.0 - 16.0, sc.1 - 18.0), (sc.0, sc.1), (sc.0 + 15.0, sc.1 + 17.0)]).pressure(0.9, 0.8).ramps(0.05, 0.1), None);
    // the ring: a loop with a rigger
    let mut r = Held::new(Tool::rigger(1.3), seed + 3);
    r.load(iron, 0.9);
    let rc = (top.0 + 5.0, top.1 - 6.0);
    let ring: Vec<(f32, f32)> = (0..=12).map(|i| {
        let a = i as f32 / 12.0 * std::f32::consts::TAU + 2.3;
        (rc.0 + a.cos() * 7.0, rc.1 + a.sin() * 6.0)
    }).collect();
    c.drag(&mut r, &Gesture::new(ring).pressure(0.7, 0.7).ramps(0.05, 0.05).shake(0.3), None);
    c.dry();
    // rust and a glint of the glow along the upper edges
    let mut g = Held::new(Tool { ragged: 0.6, ..Tool::round_sable(1.8) }, seed + 4);
    g.load(rust, 0.5);
    c.drag(&mut g, &Gesture::new(vec![(crown.0 + 6.0, crown.1 - 6.0), (top.0 - 2.0, top.1 - 2.5)]).pressure(0.4, 0.25).ramps(0.2, 0.4), None);
    g.reload(rust, 0.4);
    c.drag(&mut g, &Gesture::new(vec![(crown.0 + 24.0, crown.1 + 3.0), (crown.0 + 44.0, crown.1 - 5.0)]).pressure(0.35, 0.25).ramps(0.2, 0.4), None);
    c.dry();
}

/// A woman in a long dark dress, seen from behind, standing still, a dusky
/// red shawl over her shoulders, hair gathered up. Local gestures in figure
/// heights (u across, v up), like `figures.rs`.
fn paint_woman(c: &mut Canvas, pal: &paint::Palette, at: (f32, f32), size: f32, seed: u64) {
    use paint::{Hand, Mark};
    let mut h = Hand::new(at, size, seed);
    let dress = pal.paint(hex("#1f2320"), 0.12);
    let shawl = pal.paint(hex("#5a2a22"), 0.15);
    let hair = pal.paint(hex("#3b2a1c"), 0.2);
    let skin = pal.paint(hex("#b58e70"), 0.2);
    // skirt: strokes from the waist down, flaring to the hem
    let mut b = h.take(Tool::round_sable, 0.07, dress, 1.0);
    for (i, (u0, u1)) in [(-0.05f32, -0.12f32), (0.05, 0.12), (-0.02, -0.05), (0.02, 0.05), (0.0, 0.0)].iter().enumerate() {
        if i % 2 == 0 {
            b.reload(dress, 1.0);
        }
        h.mark(c, &mut b, Mark { pts: &[(*u0, 0.6), ((u0 + u1) * 0.5, 0.3), (*u1, 0.01)], pressure: (0.6, 1.0), ramps: (0.05, 0.05) }, None);
    }
    b.reload(dress, 1.0);
    h.line(c, &mut b, &[(-0.125, 0.02), (0.0, 0.005), (0.125, 0.02)], 0.8, 0.8);
    // bodice
    for u in [-0.035f32, 0.035, 0.0] {
        b.reload(dress, 0.9);
        h.mark(c, &mut b, Mark { pts: &[(u * 1.2, 0.82), (u, 0.7), (u * 1.1, 0.58)], pressure: (0.7, 0.7), ramps: (0.05, 0.1) }, None);
    }
    c.dry();
    // shawl: over the shoulders, pointed down the back
    let mut s = h.take(Tool::round_sable, 0.05, shawl, 1.0);
    h.mark(c, &mut s, Mark { pts: &[(-0.08, 0.8), (-0.04, 0.84), (0.04, 0.84), (0.08, 0.8)], pressure: (0.8, 0.8), ramps: (0.05, 0.1) }, None);
    s.reload(shawl, 1.0);
    h.mark(c, &mut s, Mark { pts: &[(-0.07, 0.8), (-0.02, 0.72), (0.0, 0.64)], pressure: (0.8, 0.3), ramps: (0.05, 0.4) }, None);
    s.reload(shawl, 1.0);
    h.mark(c, &mut s, Mark { pts: &[(0.07, 0.8), (0.02, 0.72), (0.0, 0.64)], pressure: (0.8, 0.3), ramps: (0.05, 0.4) }, None);
    // arms hanging, in the shawl
    s.reload(shawl, 0.8);
    h.mark(c, &mut s, Mark { pts: &[(-0.085, 0.79), (-0.1, 0.68), (-0.09, 0.57)], pressure: (0.6, 0.5), ramps: (0.05, 0.2) }, None);
    h.mark(c, &mut s, Mark { pts: &[(0.085, 0.79), (0.1, 0.68), (0.09, 0.57)], pressure: (0.6, 0.5), ramps: (0.05, 0.2) }, None);
    c.dry();
    // neck, head, hair gathered in a knot
    let mut n = h.take(Tool::round_sable, 0.025, skin, 0.5);
    h.dab(c, &mut n, 0.0, 0.86, 0.02, std::f32::consts::FRAC_PI_2, 0.7);
    let mut hd = h.take(Tool::round_sable, 0.06, hair, 0.6);
