p='paintings/src/bin/fresh_coast.rs'
s=open(p).read()
# ---- ship
a=s.index('/// A brig seen from astern-quarter')
b=s.index('/// An old stocked anchor')
s=s[:a]+'''/// A brig seen from the quarter, standing out to sea (heading right, away):
/// dark hull, two masts with three square sails each, a jib, yards and
/// stays. Against the glow the sails are a dim warm grey, lit only along
/// their left edges. `s` scales it (1 = the near brig).
fn paint_ship(c: &mut Canvas, pal: paint::Palette, at: (f32, f32), s: f32, seed: u64) {
    let (x, y) = at;
    let mut rng = Rng::new(seed);
    let hull = pal.paint(hex("#1e1a17"), 0.12);
    let line = pal.paint(hex("#27231f"), 0.15);
    let lit = pal.paint(hex("#b3a288"), 0.3);
    // hull: a long stroke for the side, a shorter one under it; the bow
    // (right) rises a little
    let mut b = Held::new(Tool::round_sable(5.0 * s), seed);
    b.load(hull, 0.9);
    c.drag(&mut b, &Gesture::new(vec![(x - 20.0 * s, y - 4.5 * s), (x, y - 4.0 * s), (x + 24.0 * s, y - 6.0 * s)]).pressure(0.9, 0.8).ramps(0.05, 0.15).shake(0.3), None);
    b.reload(hull, 0.9);
    c.drag(&mut b, &Gesture::new(vec![(x - 17.0 * s, y - 1.0 * s), (x + 18.0 * s, y - 1.5 * s)]).pressure(0.8, 0.6).ramps(0.05, 0.3).shake(0.3), None);
    c.dry();
    // the reflection: broken dark touches under the hull
    let mut r = Held::new(Tool::round_sable(1.6 * s.max(0.4)), seed + 9);
    for i in 0..5 {
        r.reload(pal.paint(hex("#3a3a40"), 0.3), 0.5);
        let yy = y + (1.0 + i as f32 * 1.6) * s;
        let w = (16.0 - i as f32 * 2.5) * s;
        let x0 = x - w + rng.normal() * 1.5 * s;
        c.drag(&mut r, &Gesture::new(vec![(x0, yy), (x0 + 2.0 * w * rng.range(0.6, 1.0), yy)]).pressure(0.5, 0.35).ramps(0.2, 0.4), None);
    }
    // masts (fore at the right, main at the left), with a slight rake
    let masts = [(-6.0f32, 88.0f32, 0.93f32), (11.0, 82.0, 1.0)];
    let mut m = Held::new(Tool::rigger(0.9 * s.max(0.45)), seed + 1);
    for &(mx, top, _) in &masts {
        m.reload(line, 0.9);
        c.drag(&mut m, &Gesture::new(vec![(x + mx * s, y - 5.0 * s), (x + mx * s - 1.0 * s, y - top * s)]).pressure(0.7, 0.4).ramps(0.0, 0.2).shake(0.15), None);
    }
    c.dry();
    // square sails: each one a single downward drag of a soft flat as wide
    // as the sail, bellying a little; the main (left) is a shade lighter,
    // the fore sits behind it
    for (mi, &(mx, top, tone)) in masts.iter().enumerate() {
        let tiers = [(0.2f32, 0.43f32, 13.0f32), (0.46, 0.66, 11.0), (0.69, 0.84, 8.0)];
        for (ti, &(a, bb, half)) in tiers.iter().enumerate() {
            let cx = x + mx * s - (a + bb) * 0.5 * s;
            let (ya, yb) = (y - top * s * bb, y - top * s * a);
            let col = mix(hex("#4a4642"), hex("#6d655d"), tone * (0.4 + 0.2 * ti as f32) - mi as f32 * 0.2, Mix::Light);
            let flat = Tool { stiffness: 0.3, ragged: 0.12, lay: 1.0, push: 0.04, splay: 0.05, ..Tool::hog_flat(half * 2.0 * s) };
            let mut sb = Held::new(flat, seed + 20 + (mi * 3 + ti) as u64);
            sb.load(pal.paint(col, 0.15), 0.9);
            let belly = 1.2 * s;
            c.drag(&mut sb, &Gesture::new(vec![(cx, ya), (cx + belly, 0.5 * (ya + yb)), (cx + 0.3 * s, yb)]).pressure(0.9, 0.9).ramps(0.02, 0.05).orient(Orient::Across).shake(0.2), None);
        }
    }
    c.dry();
    // jib and fore staysail forward of the foremast: triangles, filled with
    // a few strokes of a small round
    let mut j = Held::new(Tool::round_sable(2.6 * s), seed + 3);
    let fx = x + 11.0 * s;
    for k in 0..5 {
        j.reload(pal.paint(hex("#5a544e"), 0.2), 0.7);
        let t = k as f32 / 4.0;
        c.drag(&mut j, &Gesture::new(vec![(fx + 2.0 * s, y - (70.0 - 6.0 * t) * s), (fx + (6.0 + 12.0 * t) * s, y - (14.0 + 4.0 * t) * s)]).pressure(0.3, 0.8).ramps(0.1, 0.1).shake(0.2), None);
    }
    c.dry();
    // yards, stays, a pennant, and the glow along the sails' left edges
    let mut rg = Held::new(Tool::rigger(0.4 * s.max(0.7)), seed + 4);
    for &(mx, top, _) in &masts {
        for &(a, half) in &[(0.43f32, 14.0f32), (0.66, 12.0), (0.84, 8.5)] {
            rg.reload(line, 0.6);
            let yy = y - top * s * a;
            let cx = x + mx * s - a * s;
            c.drag(&mut rg, &Gesture::line((cx - half * s, yy + 0.4 * s), (cx + half * s, yy - 0.3 * s)).pressure(0.45, 0.45).ramps(0.0, 0.0).shake(0.1), None);
        }
    }
    rg.reload(line, 0.5);
    for (a, b2) in [((x + 10.0 * s, y - 82.0 * s), (x + 33.0 * s, y - 8.0 * s)), ((x - 7.0 * s, y - 88.0 * s), (x - 22.0 * s, y - 5.0 * s)), ((x - 7.0 * s, y - 88.0 * s), (x + 10.0 * s, y - 82.0 * s))] {
        c.drag(&mut rg, &Gesture::line(a, b2).pressure(0.3, 0.3).ramps(0.0, 0.0).shake(0.1), None);
    }
    let mut pn = Held::new(Tool::round_sable(1.4 * s.max(0.6)), seed + 5);
    pn.load(pal.paint(hex("#6b2a20"), 0.2), 0.6);
    c.drag(&mut pn, &Gesture::new(vec![(x - 7.0 * s, y - 88.0 * s), (x - 1.0 * s, y - 89.5 * s), (x + 4.0 * s, y - 88.5 * s)]).pressure(0.6, 0.15).ramps(0.0, 0.6), None);
    if s > 0.5 {
        let mut lb = Held::new(Tool { ragged: 0.4, ..Tool::round_sable(1.5 * s) }, seed + 6);
        for &(mx, top, _) in &masts[..1] {
            for &(a, bb, half) in &[(0.2f32, 0.43f32, 13.0f32), (0.46, 0.66, 11.0), (0.69, 0.84, 8.0)] {
                lb.reload(lit, 0.45);
                let cx = x + mx * s - (a + bb) * 0.5 * s;
                let ex = cx - half * s + 1.0 * s;
                c.drag(&mut lb, &Gesture::new(vec![(ex, y - top * s * bb + 1.0), (ex + 0.8 * s, y - top * s * (a + bb) * 0.5), (ex + 0.3 * s, y - top * s * a - 1.0)]).pressure(0.45, 0.35).ramps(0.1, 0.3), None);
            }
        }
    }
    c.dry();
}

